export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, { listener: Listener; once: boolean }[]>();

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ listener, once: false });
      return listeners.get(event)!.length;
    },
    once(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ listener, once: true });
      return listeners.get(event)!.length;
    },
    off(event, listener) {
      const arr = listeners.get(event);
      if (!arr) return false;
      for (let i = 0; i < arr.length; i++) {
        if (arr[i].listener === listener) {
          arr.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event, payload) {
      const arr = listeners.get(event);
      if (!arr || arr.length === 0) return [];
      const results: unknown[] = [];

      for (const entry of [...arr]) {
        results.push(entry.listener(payload));
        if (entry.once) {
          const idx = listeners.get(event)!.findIndex(e => e === entry);
          if (idx !== -1) {
            listeners.get(event)!.splice(idx, 1);
          }
        }
      }

      return results;
    },
    listenerCount(event) {
      const arr = listeners.get(event);
      return arr ? arr.length : 0;
    },
  };
}

export function createRateLimiter() {
    const LIMIT = 3;
    const WINDOW_MS = 1000;
    const state = new Map<string, { count: number; start: number }>();

    function getRecord(key: string, nowMs: number): { count: number; start: number } {
        let rec = state.get(key);
        if (!rec) {
            state.set(key, { count: 0, start: nowMs });
            return rec!;
        }
        if (nowMs - rec.start >= WINDOW_MS) {
            rec.count = 0;
            rec.start = nowMs;
        }
        return rec;
    }

    function allow(key: string, nowMs: number): boolean {
        const rec = getRecord(key, nowMs);
        if (rec.count < LIMIT) {
            rec.count++;
            return true;
        }
        return false;
    }

    function remaining(key: string, nowMs: number): number {
        const rec = getRecord(key, nowMs);
        const rem = LIMIT - rec.count;
        return rem > 0 ? rem : 0;
    }

    function reset(key: string): void {
        state.delete(key);
    }

    return { allow, remaining, reset };
}

