  const deleteTodo = (id: number): boolean => {
    return todoMap.delete(id);
  };

  const listTodos = (): Todo[] => {
    return Array.from(todoMap.values());
  };

  const listCompleted = (): Todo[] => {
    const completed: Todo[] = [];
    for (const todo of todoMap.values()) {
      if (todo.completed) completed.push(todo);
    }
