class _CalculatorImpl {
  private current = 0;
  private memory = 0;
  add(n: number): this { this.current += n; return this; }
  subtract(n: number): this { this.current -= n; return this; }
  multiply(n: number): this { this.current *= n; return this; }
  divide(n: number): this {
    if (n === 0) throw new Error('Division by zero');
    this.current /= n;
    return this;
  }
  clear(): this { this.current = 0; return this; }
  result(): number { return this.current; }
  memoryStore(): this { this.memory = this.current; return this; }
  memoryRecall(): number { return this.memory; }
  memoryClear(): this { this.memory = 0; return this; }
  memoryAdd(): this { this.memory += this.current; return this; }
}
export function createCalculator(): Calculator {
