export function createEventEmitter() {
  type Listener = (...args: any[]) => any;
  type ListenerEntry = {
    listener: Listener;
    once: boolean;
  };

  const events = new Map<string, ListenerEntry[]>();

  function on(event: string, listener: Listener): number {
    const listeners = events.get(event) || [];
    listeners.push({ listener, once: false });
    events.set(event, listeners);
    return listeners.length;
  }

  function once(event: string, listener: Listener): number {
    const listeners = events.get(event) || [];
    listeners.push({ listener, once: true });
    events.set(event, listeners);
    return listeners.length;
  }

  function off(event: string, listener: Listener): boolean {
    const listeners = events.get(event);
    if (!listeners) return false;

    for (let i = 0; i < listeners.length; i++) {
      if (listeners[i].listener === listener) {
        listeners.splice(i, 1);
        return true;
      }
    }
    return false;
  }

  function emit(event: string, payload: any): any[] {
    const listeners = events.get(event) || [];
    const results: any[] = [];
    const newListeners: ListenerEntry[] = [];

    for (const entry of listeners) {
      results.push(entry.listener(payload));
      if (!entry.once) {
        newListeners.push(entry);
      }
    }

    if (newListeners.length > 0) {
      events.set(event, newListeners);
    } else {
      events.delete(event);
    }

    return results;
  }

  function listenerCount(event: string): number {
    const listeners = events.get(event);
    return listeners ? listeners.length : 0;
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}
