export function createRateLimiter() {
  const state: Record<string, { count: number; windowStart: number }> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state[key] || { count: 0, windowStart: nowMs };
      const windowEnd = entry.windowStart + 1000;

      if (nowMs >= windowEnd) {
        entry.count = 1;
        entry.windowStart = nowMs;
        state[key] = entry;
        return true;
      }

      if (entry.count < 3) {
        entry.count++;
        state[key] = entry;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = state[key];
      if (!entry) return 3;

      const windowEnd = entry.windowStart + 1000;
      if (nowMs >= windowEnd) return 3;

      return Math.max(0, 3 - entry.count);
    },

    reset(key: string): void {
      delete state[key];
    },
  };
}
