interface Window {
  count: number;
  start: number;
}

export function createRateLimiter(): RateLimiter {
  const stores = new Map<string, Window>();

  return {
    allow(key: string, nowMs: number): boolean {
      const window = stores.get(key) || { count: 0, start: nowMs };
      window.count += 1;
      window.start = nowMs;
      stores.set(key, window);
      return window.count <= 3;
    },

    remaining(key: string, nowMs: number): number {
      const window = stores.get(key);
      if (!window) return 3;
      const { count, start } = window;
      if (nowMs - start >= 1000 || count < 0) {
        stores.set(key, { count: 0, start: nowMs });
        return 3;
      }
      return Math.max(0, 3 - count);
    },

    reset(key: string): void {
      stores.delete(key);
    },
  };
}
