const DEFAULT_TTL_MS = 1000;

export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown, expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = DEFAULT_TTL_MS) {
      const expiresAt = nowMs + (ttlMs ?? DEFAULT_TTL_MS);
      cache.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number) {
      const entry = cache.get(key);
      if (entry && nowMs < entry.expiresAt) {
        return entry.value;
      }
      return undefined;
    },
    has(key: string, nowMs: number) {
      const entry = cache.get(key);
      return entry !== undefined && nowMs < entry.expiresAt;
    },
    delete(key: string) {
      return cache.delete(key);
    },
    size(nowMs: number) {
      let count = 0;
      for (const entry of cache.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear() {
      cache.clear();
    }
  };
}
