type RateLimiterRecord = {
  windowStart: number
  remaining: number
}

export function createRateLimiter(): RateLimiter {
  const store = new Map<string, RateLimiterRecord>()
  return {
    allow(key, nowMs) {
      const record = store.get(key) ?? { windowStart: nowMs, remaining: 3 }
      if (nowMs - record.windowStart >= 1000) {
        record.windowStart = nowMs
        record.remaining = 3
      }
      if (record.remaining <= 0) return false
      record.remaining -= 1
      store.set(key, record)
      return true
    },
    remaining(key, nowMs) {
      const record = store.get(key)
      if (!record) return 3
      if (nowMs - record.windowStart >= 1000) {
        record.windowStart = nowMs
        record.remaining = 3
        store.set(key, record)
      }
      return Math.max(0, record.remaining)
    },
    reset(key) {
      store.delete(key)
    },
  }
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
