    clearCompleted(): void {
      const completedIndices = todos
        .map((todo, index) => (todo.completed ? index : -1))
        .filter((index): index is number => index !== -1)
        .reverse();
      for (const index of completedIndices) {
        todos.splice(index, 1);
      }
    },
  };
