        const arr = events.get(event);
        if (!arr) return false;
        const idx = arr.findIndex(entry => entry.fn === listener);
        if (idx === -1) return false;
        arr.splice(idx, 1);
        if (arr.length === 0) events.delete(event);
        return true;
    }

    function emit(event: string, payload?: any): any[] {
        const arr = events.get(event);
        if (!arr) return [];
        const results: any[] = [];
        for (const entry of arr.slice()) {
            results.push(entry.fn(payload));
            if (entry.once) {
                const idx = arr.indexOf(entry);
                if (idx !== -1) arr.splice(idx, 1);
