    const arr = listeners.get(event) ?? [];
    arr.push({ fn: listener, once: false });
    listeners.set(event, arr);
    return arr.length;
  }

  function once(event: string, listener: Listener): number {
    const arr = listeners.get(event) ?? [];
    arr.push({ fn: listener, once: true });
    listeners.set(event, arr);
    return arr.length;
  }

  function off(event: string, listener: Listener): boolean {
    const arr = listeners.get(event);
    if (!arr) return false;
    const idx = arr.findIndex((l) => l.fn === listener);
    if (idx === -1) return false;
    arr.splice(idx, 1);
    if (arr.length === 0) listeners.delete(event);
    else listeners.set(event, arr);
    return true;
  }

  function emit(event: string, payload: unknown): unknown[] {
    const arr = listeners.get(event);
    if (!arr) return [];
    const results: unknown[] = [];
    const remaining: Array<{ fn: Listener; once: boolean }> = [];
    for (const l of arr) {
      const res = l.fn(payload);
      results.push(res);
      if (!l.once) remaining.push(l);
    }
    if (remaining.length === 0) listeners.delete(event);
    else listeners.set(event, remaining);
    return results;
  }

  function listenerCount(event: string): number {
    return listeners.get(event)?.length ?? 0;
  }

  return { on, once, off, emit, listenerCount };
}

export type RateLimiter = {
  allow: (key: string, nowMs: number) => boolean;
  remaining: (key: string, nowMs: number) => number;
  reset: (key: string) => void;
};

export function createRateLimiter(): RateLimiter {
  const WINDOW_MS = 1000;
  const MAX_REQUESTS = 3;

  type State = {
    windowStart: number;
    count: number;
  };

  const states = new Map<string, State>();

  function getState(key: string, nowMs: number): State {
    const windowStart = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;
    let state = states.get(key);

    if (!state || state.windowStart !== windowStart) {
      state = { windowStart, count: 0 };
      states.set(key, state);
    }

    return state;
  }

  function allow(key: string, nowMs: number): boolean {
    const state = getState(key, nowMs);
    if (state.count < MAX_REQUESTS) {
      state.count++;
      return true;
    }
    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const state = getState(key, nowMs);
    const remaining = MAX_REQUESTS - state.count;
    return remaining > 0 ? remaining : 0;
  }

  function reset(key: string): void {
    states.delete(key);
  }

  return { allow, remaining, reset };
}

