}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  type Entry = { windowStart: number; count: number };
  const store = new Map<string, Entry>();

  function allow(key: string, nowMs: number): boolean {
    let entry = store.get(key);
    if (!entry) {
      entry = { windowStart: nowMs, count: 0 };
      store.set(key, entry);
    } else if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.count = 0;
    }

    if (entry.count < limit) {
      entry.count++;
      return true;
    }
    return false;
  }

  function remaining(key: string, nowMs: number): number {
    let entry = store.get(key);
    if (!entry) {
      return limit;
    }
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.count = 0;
    }
    const rem = limit - entry.count;
    return rem > 0 ? rem : 0;
  }

  function reset(key: string): void {
    store.delete(key);
  }

  return { allow, remaining, reset };
}

