export function createEventEmitter() {
  const events = new Map<string, Array<{ listener: (payload?: any) => any; once: boolean }>>();

  const on = (event: string, listener: (payload?: any) => any): number => {
    const arr = events.get(event) ?? [];
    arr.push({ listener, once: false });
    events.set(event, arr);
    return arr.length;
  };

  const once = (event: string, listener: (payload?: any) => any): number => {
    const arr = events.get(event) ?? [];
    arr.push({ listener, once: true });
    events.set(event, arr);
    return arr.length;
  };

  const off = (event: string, listener: (payload?: any) => any): boolean => {
    const arr = events.get(event);
    if (!arr) return false;
    const idx = arr.findIndex(entry => entry.listener === listener);
    if (idx === -1) return false;
    arr.splice(idx, 1);
    if (arr.length === 0) {
      events.delete(event);
    } else {
      events.set(event, arr);
    }
    return true;
  };

  const emit = (event: string, payload?: any): any[] => {
    const arr = events.get(event);
    if (!arr) return [];
    const results: any[] = [];
    const remaining: Array<{ listener: (payload?: any) => any; once: boolean }> = [];
    for (const entry of arr) {
      const res = entry.listener(payload);
      results.push(res);
      if (!entry.once) {
        remaining.push(entry);
      }
    }
    if (remaining.length === 0) {
      events.delete(event);
    } else {
      events.set(event, remaining);
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    const arr = events.get(event);
    return arr ? arr.length : 0;
  };

  return { on, once, off, emit, listenerCount };
}

export type Listener = (payload: unknown) => unknown;

export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  return {
    on(event, listener) {
      let arr = listeners.get(event);
      if (!arr) {
        arr = [];
        listeners.set(event, arr);
      }
      arr.push({ fn: listener, once: false });
      return arr.length;
    },

    once(event, listener) {
      let arr = listeners.get(event);
      if (!arr) {
        arr = [];
        listeners.set(event, arr);
      }
      arr.push({ fn: listener, once: true });
      return arr.length;
    },

    off(event, listener) {
      const arr = listeners.get(event);
      if (!arr) return false;
      for (let i = 0; i < arr.length; i++) {
        if (arr[i].fn === listener) {
          arr.splice(i, 1);
          if (arr.length === 0) listeners.delete(event);
          return true;
        }
      }
      return false;
    },

    emit(event, payload) {
      const arr = listeners.get(event);
      if (!arr) return [];
      const results: unknown[] = [];
      const toRemove: number[] = [];
      arr.forEach((item, idx) => {
        results.push(item.fn(payload));
        if (item.once) toRemove.push(idx);
      });
      for (let i = toRemove.length - 1; i >= 0; i--) {
        arr.splice(toRemove[i], 1);
      }
      if (arr.length === 0) listeners.delete(event);
      return results;
    },

    listenerCount(event) {
      const arr = listeners.get(event);
      return arr ? arr.length : 0;
    },
  };
}

