export function createRateLimiter() {
  const WINDOW_MS = 1000;
  const MAX_REQUESTS = 3;

  const state = new Map<string, { windowStart: number; count: number }>();

  const startNewWindow = (key: string, now: number) => {
    state.set(key, { windowStart: now, count: 0 });
  };

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state.get(key);
      if (!entry || nowMs >= entry.windowStart + WINDOW_MS) {
        startNewWindow(key, nowMs);
        const newEntry = state.get(key)!; // will exist
        newEntry.count++;
        return true;
      }

      if (entry.count < MAX_REQUESTS) {
        entry.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = state.get(key);
      if (!entry || nowMs >= entry.windowStart + WINDOW_MS) {
        return MAX_REQUESTS;
      }
      const remaining = MAX_REQUESTS - entry.count;
      return remaining >= 0 ? remaining : 0;
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
}
