export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const store = new Map<
    string,
    { windowStart: number; usage: number }
  >()

  const allow = (key: string, nowMs: number): boolean => {
    const entry = store.get(key)
    if (!entry || nowMs - entry.windowStart >= windowMs) {
      store.set(key, { windowStart: nowMs, usage: 1 })
      return true
    }
    if (entry.usage < limit) {
      entry.usage++
      return true
    }
    return false
  }

  const remaining = (key: string, nowMs: number): number => {
    const entry = store.get(key)
    if (!entry || nowMs - entry.windowStart >= windowMs) {
      return limit
    }
    return Math.max(0, limit - entry.usage)
  }

  const reset = (key: string): void => {
    store.delete(key)
  }

  return { allow, remaining, reset }
}

