import { EventEmitter } from "events";

/** Creates a minimal event emitter with named export APIs. */
export function createEventEmitter() {
  // Internal store of event listeners
  const events = new Map<
    string,
    Array<{ handler: (...args: any[]) => any; once: boolean }>
  >();

  // Ensure an array exists for an event
  const getList = (event: string) => {
    if (!events.has(event)) events.set(event, []);
    return events.get(event)!;
  };

  return {
    /**
     * Register a listener for an event.
     * @returns the number of listeners for that event after registration.
     */
    on(event: string, listener: (...args: any[]) => any): number {
      const list = getList(event);
      list.push({ handler: listener, once: false });
      return list.length;
    },

    /**
     * Register a one‑time listener for an event.
     * @returns the number of listeners for that event after registration.
     */
    once(event: string, listener: (...args: any[]) => any): number {
      const list = getList(event);
      list.push({ handler: listener, once: true });
      return list.length;
    },

    /**
     * Remove one matching listener for an event.
     * @returns true if a listener was removed, otherwise false.
     */
    off(event: string, listener: (...args: any[]) => any): boolean {
      const list = events.get(event);
      if (!list) return false;
      const idx = list.findIndex((entry) => entry.handler === listener);
      if (idx === -1) return false;
      list.splice(idx, 1);
      if (list.length === 0) events.delete(event);
      return true;
    },

    /**
     * Emit an event with a payload.
     * @returns an array of return values from each listener.
     */
    emit(event: string, payload: any): any[] {
      const list = events.get(event);
      if (!list) return [];
      const results: any[] = [];
      // Take a snapshot to avoid mutation issues during iteration
      const snapshot = [...list];
      for (const entry of snapshot) {
        results.push(entry.handler(payload));
      }
      // Remove once listeners after all have been called
      const remaining = list.filter((entry) => !entry.once);
      if (remaining.length) {
        events.set(event, remaining);
      } else {
        events.delete(event);
      }
      return results;
    },

    /**
     * Get current listener count for an event.
     */
    listenerCount(event: string): number {
      const list = events.get(event);
      return list ? list.length : 0;
    },
  };
}

export function createEventEmitter() {
  type Listener = (payload: unknown) => unknown;

  type ListenerEntry = {
    listener: Listener;
    once: boolean;
  };

  const events = new Map<string, ListenerEntry[]>();

  function getList(event: string): ListenerEntry[] {
    let list = events.get(event);
    if (!list) {
      list = [];
      events.set(event, list);
    }
    return list;
  }

  const emitter = {
    on(event: string, listener: Listener): number {
      const list = getList(event);
      list.push({ listener, once: false });
      return list.length;
    },

    once(event: string, listener: Listener): number {
      const list = getList(event);
      list.push({ listener, once: true });
      return list.length;
    },

    off(event: string, listener: Listener): boolean {
      const list = events.get(event);
      if (!list) return false;
      for (let i = 0; i < list.length; i++) {
        if (list[i].listener === listener) {
          list.splice(i, 1);
          if (list.length === 0) events.delete(event);
          return true;
        }
      }
      return false;
    },

    emit(event: string, payload: unknown): unknown[] {
      const list = events.get(event);
      if (!list) return [];
      const results: unknown[] = [];
      for (let i = 0; i < list.length; ) {
        const entry = list[i];
        results.push(entry.listener(payload));
        if (entry.once) {
          list.splice(i, 1);
        } else {
          i++;
        }
      }
      if (list.length === 0) events.delete(event);
      return results;
    },

    listenerCount(event: string): number {
      const list = events.get(event);
      return list ? list.length : 0;
    },
  } as {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, payload: unknown): unknown[];
    listenerCount(event: string): number;
  };

  return emitter;
}

export function createRateLimiter() {
    const MAX_REQUESTS = 3;
    const WINDOW_MS = 1000;
    const state = new Map<string, { windowStart: number; count: number }>();

    function allow(key: string, nowMs: number): boolean {
        const entry = state.get(key);
        if (!entry) {
            state.set(key, { windowStart: nowMs, count: 1 });
            return true;
        }
        if (nowMs >= entry.windowStart + WINDOW_MS) {
            // new window
            entry.windowStart = nowMs;
            entry.count = 1;
            return true;
        } else {
            if (entry.count < MAX_REQUESTS) {
                entry.count += 1;
                return true;
            }
            return false;
        }
    }

    function remaining(key: string, nowMs: number): number {
        const entry = state.get(key);
        if (!entry) return MAX_REQUESTS;
        if (nowMs >= entry.windowStart + WINDOW_MS) return MAX_REQUESTS;
        const remaining = MAX_REQUESTS - entry.count;
        return remaining >= 0 ? remaining : 0;
    }

    function reset(key: string): void {
        state.delete(key);
    }

    return {
        allow,
        remaining,
        reset,
    };
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, { count: number; start: number }>();

  return {
    allow(key, nowMs) {
      let entry = store.get(key);
      if (!entry || nowMs - entry.start >= windowMs) {
        // start new window
        entry = { count: 0, start: nowMs };
        store.set(key, entry);
      }
      if (entry.count < limit) {
        entry.count += 1;
        return true;
      }
      return false;
    },

    remaining(key, nowMs) {
      const entry = store.get(key);
      if (!entry || nowMs - entry.start >= windowMs) {
        return limit;
      }
      const remaining = limit - entry.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key) {
      store.delete(key);
    },
  };
}

