 * Returns an object with a calculator and its corresponding utility methods.
 *
 * @returns {object} Calculator object
 */
function createCalculator() {
  // Initialize the calculator's state
  let currentValue = 0;

  // Initialize the memory store
  let memoryValue = 0;

  // Return an object that will be extended with calculator and utilities methods
  return {
    add: (n) => {
      currentValue += n;
      return this;
    },
    subtract: (n) => {
      currentValue -= n;
      return this;
    },
    multiply: (n) => {
      currentValue *= n;
      return this;
    },
    divide: (n) => {
      if (n === 0) {
        throw new Error('Cannot divide by zero');
      }
      currentValue /= n;
      return this;
    },
    clear: () => {
      currentValue = 0;
      return this;
    },
    result: () => currentValue,
    memoryStore: () => {
      // Store the current value in memory and keep it unchanged
      memoryValue = currentValue;
      return this;
    },
    memoryAdd: () => {
      // Add to memory without changing the current value
      memoryValue += currentValue;
      return this;
    },
    memoryClear: () => {
      // Clear the memory store while keeping the calculator's state
      memoryValue = 0;
      return this;
    },
    memoryRecall: () => {
      const result = memoryValue;
      memoryValue = 0; // Reset memory value to maintain independence from current value
      return [result, this.result()];
    }
  };
}

