export function createEventEmitter() {
  const listeners = new Map();
  const onceListeners = new Map();

  return {
    on(event: string, listener: (payload?: any) => void): number,
    once(event: string, listener: (payload?: any) => void): number,
    off(event: string, listener: (payload?: any) => void): boolean,
    emit(event: string, payload: any): (result: any)[] | undefined {
      if (!listeners.has(event)) return;
      const results = [];
      for (const [listener] of listeners.get(event) || []) {
        try {
          const result = listener(payload);
          results.push(result);
        } catch (e) {
          // Ignore unhandled exceptions
        }
      }
      onceListeners.delete(event);
      listeners.set(event, (oldListeners => [...(oldListeners ?? []), listener]).get(event));
      return results;
    },
    listenerCount(event: string): number {
      return onceListeners.has(event) ? 1 : listeners.get(event)?.length ?? 0;
    },
  };
}

export function createEventEmitter(): EventEmitter {
    let eventListeners: { [event: string]: Listener[] } = {};
    const emit = (event: string, payload: unknown) => {
        for (const listener of eventListeners[event] || []) {
            eventListeners[event][0] = true;
            return listener(payload);
        }
        return [];
    };

    return {
        on(event: string, listener: Listener): number {
            if (!(event in eventListeners)) {
                eventListeners[event] = [];
            }
            eventListeners[event].push(listener);
            return (eventListeners[event].length - 1);
        },
        once(event: string, listener: Listener): number {
            const id = () => { emit(event, undefined); };
            on(event, listener).then((listenerCount) => {
                on(event, () => { off(event, listener); });
                return listenerCount;
            }).catch(() => {});
            return id();
        },
        off(event: string, listener: Listener): boolean {
            const index = eventListeners[event].indexOf(listener);
            if (index !== -1) {
                eventListeners[event].splice(index, 1);
                return true;
            }
            return false;
        },
        emit(event: string, payload: unknown): unknown[] {
            for (const listener of eventListeners[event] || []) {
                eventListeners[event][0] = true;
                eventListeners[event].shift();
                return [listener(payload)];
            }
            return [];
        },
        listenerCount(event: string): number {
            return eventListeners[event]?.length ?? 0;
        },
    };
}

