export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  let cache: Map<string, [Date, unknown]> = new Map();

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
    const ttlMs = ttlMs ?? 1000;
    const expiresAt = new Date(nowMs + ttlMs);
    cache.set(key, [expiresAt, value]);
  }

  function get(key: string, nowMs: number): unknown {
    for (const [, value] of cache.entries()) {
      if (value[0].getTime() <= nowMs) continue;
      return value[1];
    }
    return undefined;
  }

  function has(key: string, nowMs: number): boolean {
    return cache.has(key);
  }

  function delete(key: string): boolean {
    return cache.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const [, value] of cache.entries()) {
      if (value[0].getTime() <= nowMs) continue;
      ++count;
    }
    return count;
  }

  function clear() {
    cache.clear();
  }

  return { set, get, has, delete, size, clear };
}

export function createTtlCache(): TtlCache {
  let cache: { [key: string]: unknown } = {};
  let expiresAt: number | null = null;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      if (ttlMs === undefined) ttlMs = 0;
      const expirationMs = nowMs + ttlMs;

      cache[key] = value;
      expiresAt = expirationMs;
    },
    get(key: string, nowMs: number): unknown {
      if (!cache.hasOwnProperty(key)) return undefined;
      const currentExpiration = nowMs + 1000; // fixed default TTL
      if (currentExpiration >= expiresAt) delete cache[key];
      return cache[key];
    },
    has(key: string, nowMs: number): boolean {
      if (!cache.hasOwnProperty(key)) return false;
      return true;
    },
    delete(key: string): boolean {
      const currentKey = cache[key];
      if (currentKey !== undefined) {
        delete cache[key];
        return true;
      }
      return false;
    },
    size(nowMs: number): number {
      let count = 0;

      for (const key in cache) {
        const expiration = nowMs + 1000; // fixed default TTL
        if (expiration >= expiresAt) continue;
        count++;
      }

      return count;
    },
    clear(): void {
      cache = {};
      expiresAt = null;
    }
  };
}

