export function createTodoApp(): TodoApp {
    let todos: Map<number, Todo> = new Map();

    const addTodo = (text: string): Todo => {
        let id = [...todos.keys()].length;
        return { id, text, completed: false };
    }

    export function getTodo(id: number): Todo | undefined {
        return todos.get(id);
    }

    export function toggleTodo(id: number): void {
        if (!todos.has(id)) return; // do nothing on missing id
        const todo = todos.get(id) as Todo;
        todos.set(id, { ...todo, completed: !todo.completed });
    }

    export function deleteTodo(id: number): boolean {
        todos.delete(id);
        return true;
    }

    export function listTodos(): Todo[] {
        return [...todos.values()];
    }

    export function listCompleted(): Todo[] {
        return Array.from(todos.values()).filter(todo => todo.completed).map(todo => ({ ...todo, id: -1 }));
    }

    export function listPending(): Todo[] {
        return Array.from(todos.values()).filter(todo => !todo.completed).map(todo => ({ ...todo, id: undefined }));
    }

    export function clearCompleted(): void {
        todos = new Map([...todos].filter(([_, todo]) => !(todo as any).completed));
    }
}
