const ttlCache = {
  set: (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    const ttlMs = ttlMs === undefined ? 1000 : ttlMs;
    if (typeof value !== 'object') {
      this.data[key] = { value, expiresAt: nowMs + ttlMs };
    } else {
      this.data[key] = value;
      while (this.data[key].expiresAt < nowMs) {
        delete this.data[key];
        this.has(key)
      }
    }
  },
  get: (key: string, now Ms): unknown => {
    const expiresAt = this.data[key]?.expiresAt;
    return exists(this.data[key]) && now Ms < expiresAt ? this.data[key].value : undefined
  },
  has: (key: string, nowMs): boolean => key in this.data,
  delete: (key: string): boolean => {
    if (this.has(key)) {
      const data = this.data[key];
      delete this.data[key];
      return true;
    }
    return false;
  },
  size: (nowMs): number =>
    Object.keys(this.data).reduce((size, key) => (this.has(key) && expiresAt > nowMs ? 1 : 0), size),
  clear: (): void => (this.data = {}),
};
