type Listener<T = any> = (payload: T) => any;
type EventMap = Record<string, Array<{ listener: Listener; once: boolean }>>;

export function createEventEmitter<T extends EventMap = EventMap>() {
    const listeners: T = {} as any;

    function on<K extends keyof T>(event: K, listener: T[K] extends Listener<infer P> ? Listener<P> : Listener) {
        if (!listeners[event]) listeners[event] = [];
        listeners[event].push({ listener, once: false });
        return listeners[event].length;
    }

    function once<K extends keyof T>(event: K, listener: T[K] extends Listener<infer P> ? Listener<P> : Listener) {
        if (!listeners[event]) listeners[event] = [];
        listeners[event].push({ listener, once: true });
        return listeners[event].length;
    }

    function off<K extends keyof T>(event: K, listener: T[K] extends Listener<infer P> ? Listener<P> : Listener) {
        if (!listeners[event]) return false;
        const index = listeners[event].findIndex(l => l.listener === listener && !l.once);
        if (index === -1) return false;
        listeners[event].splice(index, 1);
        return true;
    }

    function emit<K extends keyof T>(event: K, payload: Parameters<T[K]>[0]) {
        if (!listeners[event]) return [];
        const results: any[] = [];
        const remainingListeners = listeners[event].filter(l => {
            results.push(l.listener(payload));
            return !l.once;
        });
        listeners[event] = remainingListeners;
        return results;
    }

    function listenerCount<K extends keyof T>(event: K) {
        return listeners[event]?.length || 0;
    }

    return { on, once, off, emit, listenerCount };
}
