export function createEventEmitter() {
  const listeners = new Map<string, Listener[]>();
  const onceListeners = new Map<string, Listener[]>();

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push(listener);
      return listeners.get(event)!.length;
    },

    once(event, listener) {
      if (!onceListeners.has(event)) {
        onceListeners.set(event, []);
      }
      onceListeners.get(event)!.push(listener);
      return onceListeners.get(event)!.length;
    },

    off(event, listener) {
      if (listeners.has(event)) {
        const eventListeners = listeners.get(event)!;
        const index = eventListeners.indexOf(listener);
        if (index !== -1) {
          eventListeners.splice(index, 1);
          return true;
        }
      }
      return false;
    },

    emit(event, payload) {
      const results: unknown[] = [];
      const emitOnce = (listenersMap: Map<string, Listener[]>) => {
        if (listenersMap.has(event)) {
          const eventListeners = listenersMap.get(event)!;
          for (const listener of eventListeners) {
            results.push(listener(payload));
          }
          if (listenersMap === onceListeners) {
            listenersMap.delete(event);
          }
        }
      };
      emitOnce(listeners);
      emitOnce(onceListeners);
      return results;
    },

    listenerCount(event) {
      return (listeners.get(event)?.length || 0) + (onceListeners.get(event)?.length || 0);
    }
  };
}
