type RateLimiter = {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
};

export function createRateLimiter(): RateLimiter {
    const state: Record<string, { count: number; windowStart: number }> = {};

    return {
        allow(key: string, nowMs: number): boolean {
            const entry = state[key] || { count: 0, windowStart: nowMs };
            const elapsed = nowMs - entry.windowStart;
            const windowElapsed = elapsed >= 1000;

            if (windowElapsed) {
                entry.count = 0;
                entry.windowStart = nowMs;
            }

            if (entry.count < 3) {
                entry.count++;
                state[key] = entry;
                return true;
            }

            return false;
        },

        remaining(key: string, nowMs: number): number {
            const entry = state[key] || { count: 0, windowStart: nowMs };
            const elapsed = nowMs - entry.windowStart;
            const windowElapsed = elapsed >= 1000;

            if (windowElapsed) {
                entry.count = 0;
                entry.windowStart = nowMs;
            }

            return Math.max(0, 3 - entry.count);
        },

        reset(key: string): void {
            delete state[key];
        }
    };
}
