type Listener<T = any> = (payload: T) => void | Promise<void>;

interface EventEmitter<TEvents extends Record<string, any>> {
    on<K extends keyof TEvents>(event: K, listener: Listener<TEvents[K]>): number;
    once<K extends keyof TEvents>(event: K, listener: Listener<TEvents[K]>): number;
    off<K extends keyof TEvents>(event: K, listener: Listener<TEvents[K]>): boolean;
    emit<K extends keyof TEvents>(event: K, payload: TEvents[K]): ReturnType<Listener<TEvents[K>>>[];
    listenerCount<T extends string>(event: T): number;
}

function createEventEmitter<TEvents extends Record<string, any>>(): EventEmitter<TEvents> {
    const listeners: Record<string, Map<Listener, () => void>> = {};

    return {
        on(event, listener) {
            if (!listeners[event]) listeners[event] = new Map();
            listeners[event]!.set(listener, listener);
            return listeners[event]!.size;
        },

        once(event, listener) {
            const onceWrapper = async (...args: any[]) => {
                listener(...args);
                listeners[event]!.delete(onceWrapper);
            };
            if (!listeners[event]) listeners[event] = new Map();
            listeners[event]!.set(onceWrapper, onceWrapper as Listener);
            return listeners[event]!.size;
        },

        off(event, listener) {
            const removed = listeners[event]?.has(listener) && listeners[event]!.delete(listener);
            return Boolean(removed);
        },

        emit(event, payload) {
            const currentListeners = listeners[event];
            if (!currentListeners) return [];

            const returnValues: any[] = [];
            for (const [listener] of currentListeners) {
                const result = listener(payload);
                Promise.resolve(result).then((val) => returnValues.push(val));
            }
            return returnValues;
        },

        listenerCount(event) {
            return listeners[event]?.size || 0;
        },
    };
}
