interface EventEmitter {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, payload: unknown): unknown[];
    listenerCount(event: string): number;
}

type Listener = (payload: unknown) => unknown;

function createEventEmitter(): EventEmitter {
    const events: Record<string, Listener[]> = {};
    const onceListeners: Record<string, { listener: Listener; count: number }> = {};

    function on(event: string, listener: Listener): number {
        if (!events[event]) {
            events[event] = [];
        }
        events[event].push(listener);
        return events[event].length;
    }

    function once(event: string, listener: Listener): number {
        if (!onceListeners[event]) {
            onceListeners[event] = { listener: null as Listener, count: 0 };
            events[event] = [];
        }
        if (!onceListeners[event]!.listener) {
            onceListeners[event]!.listener = listener;
        }
        const key = `${event}-${Date.now()}`;
        events[event].push(onceListeners[event]!.listener);
        onceListeners[event]!.count++;
        return events[event].length;
    }

    function off(event: string, listener: Listener): boolean {
        if (events[event]) {
            const index = events[event].indexOf(listener);
            if (index !== -1) {
                events[event].splice(index, 1);
                return true;
            }
        }
        return false;
    }

    function emit(event: string, payload: unknown): unknown[] {
        const result: unknown[] = [];
        const listeners = events[event] || [];
        listeners.forEach(listener => {
            const res = listener(payload);
            result.push(res);
        });
        return result;
    }

    function listenerCount(event: string): number {
        return (events[event] || []).length;
    }

    return {
        on,
        once,
        off,
        emit,
        listenerCount,
    };
}

export { createEventEmitter };
