export const createRateLimiter = (): RateLimiter => {
    type KeyState = {
        count: number;
        startMs: number;
    };

    const state: Record<string, KeyState> = {};

    return {
        allow(key: string, nowMs: number): boolean {
            const existing = state[key];
            const windowMs = 1000;
            const remainingTokens = existing ? windowMs - (nowMs - existing.startMs) : 0;
            const isFreshWindow = remainingTokens <= 0;

            if (isFreshWindow) {
                state[key] = { count: 1, startMs: nowMs };
                return true;
            }

            if (existing.count >= 3) {
                return false;
            }

            state[key].count += 1;
            return true;
        },
        remaining(key: string, nowMs: number): number {
            const existing = state[key];
            if (!existing) return 3;

            const windowMs = 1000;
            const timeInWindow = nowMs - existing.startMs;
            const remainingTokens = windowMs - timeInWindow;

            if (remainingTokens <= 0) {
                state[key] = { count: 0, startMs: nowMs };
                return 3;
            }

            return Math.max(3 - existing.count, 0);
        },
        reset(key: string): void {
            delete state[key];
        }
    };
};
