export function createRateLimiter(): RateLimiter {
    return {
        allow(key: string, nowMs: number): boolean {
            const entry = this as any;
            const limit = 3;
            const windowMs = 1000;

            if (!entry._keys) {
                entry._keys = new Map<string, { count: number, windowStart: number }>();
            }

            let entryData = entry._keys.get(key);
            if (!entryData) {
                entryData = { count: 0, windowStart: nowMs };
                entry._keys.set(key, entryData);
                entryData.count++;
                return true;
            }

            if (nowMs - entryData.windowStart >= windowMs) {
                entryData.count = 0;
                entryData.windowStart = nowMs;
            }

            if (entryData.count < limit) {
                entryData.count++;
                return true;
            }

            return false;
        },

        remaining(key: string, nowMs: number): number {
            const entry = this as any;
            const limit = 3;

            if (!entry._keys) {
                entry._keys = new Map<string, { count: number, windowStart: number }>();
            }

            let entryData = entry._keys.get(key);
            if (!entryData) {
                return limit;
            }

            if (nowMs - entryData.windowStart >= entryData.windowStart) {
                entryData.count = 0;
                entryData.windowStart = nowMs;
            }

            return limit - entryData.count;
        },

        reset(key: string): void {
            const entry = this as any;
            if (entry._keys) {
                entry._keys.delete(key);
            }
        }
    };
}

interface RateLimiter {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
}
