export function createEventEmitter(): EventEmitter {
  const eventListeners: Map<string, Listener[]> = new Map();
  const onceListeners: Map<string, { listener: Listener, count: number }[]> = new Map();

  return {
    on(event, listener) {
      if (!eventListeners.has(event)) {
        eventListeners.set(event, []);
      }
      eventListeners.get(event)?.push(listener);
      return eventListeners.get(event)!.length;
    },
    once(event, listener) {
      if (!onceListeners.has(event)) {
        onceListeners.set(event, []);
      }
      const listeners = onceListeners.get(event)!;
      listeners.push({ listener, count: listeners.length + 1 });
      return listeners.length;
    },
    off(event, listener) {
      if (eventListeners.has(event)) {
        const listeners = eventListeners.get(event)!;
        const index = listeners.indexOf(listener);
        if (index > -1) {
          listeners.splice(index, 1);
          return true;
        }
      }
      if (onceListeners.has(event)) {
        const listeners = onceListeners.get(event)!;
        for (let i = 0; i < listeners.length; i++) {
          if (listeners[i].listener === listener) {
            listeners.splice(i, 1);
            return true;
          }
        }
      }
      return false;
    },
    emit(event, payload) {
      const results: unknown[] = [];
      const onceResults: unknown[] = [];

      if (eventListeners.has(event)) {
        const listeners = eventListeners.get(event)!;
        for (const listener of listeners) {
          results.push(listener(payload));
        }
      }

      if (onceListeners.has(event)) {
        const listeners = [...onceListeners.get(event)!];
        for (const { listener } of listeners) {
          onceResults.push(listener(payload));
        }
        // Remove all once listeners after emission
        onceListeners.delete(event);
      }

      return [...results, ...onceResults];
    },
    listenerCount(event) {
      return onceListeners.has(event) && eventListeners.has(event)
        ? eventListeners.get(event)!.length + onceListeners.get(event)!.length
        : eventListeners.get(event)?.length || onceListeners.get(event)?.length || 0;
    },
  };
}
