export function createRateLimiter(): RateLimiter {
    const state: Record<string, { quota: number, lastReset: number }> = {};

    return {
        allow(key: string, nowMs: number): boolean {
            const entry = state[key] || { quota: 3, lastReset: nowMs };
            if (nowMs - entry.lastReset >= 1000) {
                state[key] = { quota: 3, lastReset: nowMs };
                return true;
            }
            if (entry.quota > 0) {
                state[key] = { ...entry, quota: entry.quota - 1 };
                return true;
            }
            return false;
        },
        remaining(key: string, nowMs: number): number {
            const entry = state[key] || { quota: 3, lastReset: nowMs };
            if (nowMs - entry.lastReset >= 1000) {
                state[key] = { quota: 3, lastReset: nowMs };
            }
            return Math.max(entry.quota, 0);
        },
        reset(key: string): void {
            state[key] = { quota: 3, lastReset: Date.now() };
        }
    };
}

interface RateLimiter {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
