export function createRateLimiter() {
  const windowSizeMs = 1000;
  const quota = 3;

  return {
    allow: (key: string, nowMs: number) => {
      const windowStartMs = ((nowMs / windowSizeMs) | 0) * windowSizeMs;
      const windowKey = `${windowStartMs}-${key}`;
      const state = (this as any)[windowKey] || {
        requests: 0,
        countdown: nowMs - windowStartMs,
      };

      if (state.countdown <= 0) {
        state.countdown = windowSizeMs - (nowMs % windowSizeMs);
      }

      if (state.requests >= quota) return false;

      state.requests++;
      state.countdown = windowStartMs + windowSizeMs;
      (this as any)[windowKey] = state;
      return true;
    },
    remaining: (key: string, nowMs: number) => {
      const windowStartMs = ((nowMs / windowSizeMs) | 0) * windowSizeMs;
      const windowKey = `${windowStartMs}-${key}`;
      const state = (this as any)[windowKey] || {
        requests: 0,
        countdown: nowMs - windowStartMs,
      };

      const elapsedMs = nowMs - windowStartMs;
      const quotaRemaining = Math.max(0, quota - state.requests);

      if (elapsedMs <= state.countdown) {
        const fullWindows = elapsedMs / windowSizeMs;
        return Math.max(quota - Math.ceil(windowStartMs + fullWindows > nowMs ? quota : state.requests), 0);
      } else {
        return Math.max(quotaRemaining, 0);
      }
    },
    reset: (key: string) => {
      const nowMs = Date.now();
      const windowKey = `(nowMs: ${nowMs})-${key}`;
      delete ((this as any)[windowKey]);
    },
  };
}
