function createCalculator(): Calculator {
  let internals: CalculatorInternals = { state: 0, memory: 0 };

  function calculate(op: (state: State) => State) {
    internals.state = op(internals.state);
    return internals;
  }

  function add(n: State): Calculator {
    return calculate((state) => state + n);
  }

  function subtract(n: State): Calculator {
    return calculate((state) => state - n);
  }

  function multiply(n: State): Calculator {
    return calculate((state) => state * n);
  }

  function divide(n: State): Calculator {
    if (n === 0) throw new Error("Division by zero");
    return calculate((state) => state / n);
  }

  function clear(): Calculator {
    internals.state = 0;
    return internals;
  }

  function memoryStore(): Calculator {
    return calculate((state) => state);
