export const createRateLimiter = () => {
  const windowSizeMs = 1000;
  const requestsPerWindow = 3;

  const keysByWindow = new Map<string, { count: number; remaining: number; windowMs: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const keyInfo = keysByWindow.get(key);
      let window: { count: number; remaining: number; windowMs: number } | undefined;

      if (!keyInfo) {
        window = { count: 0, remaining: 0, windowMs: nowMs };
        keysByWindow.set(key, window);
      } else {
        const { count, remaining, windowMs } = keyInfo;
        const elapsed = nowMs - windowMs;
        if (elapsed >= windowSizeMs) {
          window = { count: 0, remaining: 0, windowMs: nextWindowStart(elapsed, nowMs) };
          keysByWindow.set(key, window);
      } else if (remaining + 1 <= requestsPerWindow) {
        const newRemaining = remaining + 1;
        const updatedInfo = { count: count + 1, remaining: newRemaining, windowMs: windowMs };
        keysByWindow.set(key, updatedInfo);
        return newRemaining <= requestsPerWindow;
      } else {
        return false;
      }
    },
    remaining(key: string, nowMs: number): number {
      const keyInfo = keysByWindow.get(key);
      const elapsed = nowMs - (keyInfo ? keyInfo.windowMs : 0);

      if (!keyInfo || elapsed >= windowSizeMs) {
        return requestsPerWindow;
      } else {
        const remaining = keyInfo.remaining + requestsPerWindow - (keyInfo.count + 1);
        return Math.min(remaining, requestsPerWindow);
      }
    },
    reset(key: string) {
      keysByWindow.delete(key);
    }
  };

  function nextWindowStart(elapsed: number, nowMs: number): number {
    return nowMs + (windowSizeMs - elapsed);
  }
};
