export function createRateLimiter() {
  const limit = 3;
  const windowSize = 1000;

  type State = { windowStart: number; count: number };
  const quotas = new Map<string, State>();

  const getState = (key: string, nowMs: number): State => {
    const expectedWindowStart = nowMs - (nowMs % windowSize);
    let state = quotas.get(key);
    if (!state) {
      state = { windowStart: expectedWindowStart, count: 0 };
      quotas.set(key, state);
      return state;
    }
    if (state.windowStart !== expectedWindowStart) {
      state.windowStart = expectedWindowStart;
      state.count = 0;
    }
    return state;
  };

  return {
    allow(key: string, nowMs: number): boolean {
      const state = getState(key, nowMs);
      if (state.count < limit) {
        state.count += 1;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = getState(key, nowMs);
      const remaining = limit - state.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key: string): void {
      quotas.delete(key);
    },
  };
}

