  const state = new Map<string, {windowStart: number; count: number}>();

  function normalize(key: string, nowMs: number, force = false) {
    const entry = state.get(key);
    if (!entry) {
      if (!force) return null;
      // initialize
      entry = {windowStart: nowMs, count: 0};
      state.set(key, entry);
      return entry;
    }

    if (!force && nowMs - entry.windowStart >= WINDOW_MS) {
      // window expired
      entry.windowStart = nowMs;
      entry.count = 0;
    }

    return entry;
  }

