    return true;
  }

  function listTodos(): Todo[] {
    return todos.slice();
  }

  function listCompleted(): Todo[] {
    const completed: Todo[] = [];
    for (const todo of todos) {
      if (todo.completed) {
        completed.push(todo);
      }
    }
    return completed;
  }

  function listPending(): Todo[] {
    const pending: Todo[] = [];
    for (const todo of todos) {
      if (!todo.completed) {
        pending.push(todo);
      }
    }
    return pending;
  }

