    const remaining: Todo[] = [];
    for (const todo of todos) {
      if (!todo.completed) {
        remaining.push(todo);
      }
    }
    todos = remaining;
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
