function createTtlCache() {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number) => {
    const ttl = ttlMs !== undefined ? ttlMs : 1000;
    const expiresAt = nowMs + ttl;
    store.set(key, { value, expiresAt });
  };

  const get = (key: string, nowMs: number): unknown => {
    const entry = store.get(key);
    if (entry && nowMs < entry.expiresAt) {
      return entry.value;
    }
    return undefined;
  };

  const has = (key: string, nowMs: number): boolean => {
    const entry = store.get(key);
    return entry && nowMs < entry.expiresAt;
  };

  const delete = (key: string): boolean => {
    return store.delete(key);
  };

  const size = (nowMs: number): number => {
    let count = 0;
    for (const entry of store.values()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  };

  const clear = () => {
    store.clear();
  };

  return { set, get, has, delete, size, clear };
}

