export function createEventEmitter() {
  const listeners = new Map<string, ((payload: any) => any)[]>();
  const getListeners = (event: string): ((payload: any) => any)[] => {
    let arr = listeners.get(event);
    if (!arr) {
      arr = [];
      listeners.set(event, arr);
    }
    return arr;
  };
  const removeListener = (event: string, listener: ((payload: any) => any)): boolean => {
    const arr = listeners.get(event);
    if (!arr) return false;
    const idx = arr.findIndex(l => l === listener);
    if (idx !== -1) {
      arr.splice(idx, 1);
      return true;
    }
    return false;
  };
  return {
    on(event: string, listener: ((payload: any) => any)): number {
      const arr = getListeners(event);
      arr.push(listener);
      return arr.length;
    },
    once(event: string, listener: ((payload: any) => any)): number {
