      arr.push(wrapper);
      return arr.length;
    },
    off(event: string, listener: ((payload: any) => any)): boolean {
      return removeListener(event, listener);
    },
    emit(event: string, payload: any): any[] {
      const arr = listeners.get(event);
      const result: any[] = [];
      if (arr) {
        const snapshot = [...arr];
        for (const fn of snapshot) {
