}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, { fn: Listener; once: boolean }[]>();

  return {
    on(event, listener) {
      let list = listeners.get(event);
      if (!list) {
        list = [];
        listeners.set(event, list);
      }
      list.push({ fn, once: false });
      return list.length;
    },

    once(event, listener) {
      let list = listeners.get(event);
      if (!list) {
        list = [];
        listeners.set(event, list);
      }
      list.push({ fn, once: true });
      return list.length;
    },

    off(event, listener) {
      const list = listeners.get(event) ?? [];
      for (let i = list.length - 1; i >= 0; i--) {
        if (list[i].fn === listener) {
          list.splice(i, 1);
          return true;
        }
      }
      return false;
    },

    emit(event, payload) {
      const list = listeners.get(event) ?? [];
      const results: unknown[] = [];
      for (let i = 0; i < list.length; i++) {
        const { fn, once } = list[i];
        const ret = fn(payload);
        results.push(ret);
        if (once) {
          list.splice(i, 1);
          i--;
        }
      }
      return results;
    },

    listenerCount(event) {
      const list = listeners.get(event) ?? [];
      return list.length;
    }
  };
}

export function createRateLimiter(): {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
} {
  const WINDOW = 1000;
  const LIMIT = 3;
  type WindowState = { last: number; count: number };
  const windows = new Map<string, WindowState>();

  const getCurrentWindow = (nowMs: number): number => nowMs - (nowMs % WINDOW);

  return {
    allow(key: string, nowMs: number): boolean {
      const curWindow = getCurrentWindow(nowMs);
      let state = windows.get(key);
      if (!state || state.last !== curWindow) {
        state = { last: curWindow, count: 0 };
        windows.set(key, state);
      }
      if (state.count < LIMIT) {
        state.count += 1;
        windows.set(key, state);
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const curWindow = getCurrentWindow(nowMs);
      const state = windows.get(key);
      if (state && state.last === curWindow) {
        const remaining = LIMIT - state.count;
        return remaining > 0 ? remaining : 0;
      }
      return LIMIT;
    },

    reset(key: string): void {
      windows.delete(key);
    },
  };
}

