  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  type Bucket = {
    count: number
    windowStart: number
  }

  const entries = new Map<string, Bucket>()
  const limit = 3
  const windowMs = 1000

  return {
    allow(key: string, nowMs: number): boolean {
      let bucket = entries.get(key)
      const expired = bucket === undefined || nowMs - (bucket.windowStart ?? nowMs) >= windowMs
      if (expired) {
        bucket = { count: 0, windowStart: nowMs }
      }
      if (bucket.count >= limit) {
        return false
      }
      bucket.count += 1
      entries.set(key, bucket)
      return true
    },

    remaining(key: string, nowMs: number): number {
      let bucket = entries.get(key)
      const expired = bucket === undefined || nowMs - (bucket.windowStart ?? nowMs) >= windowMs
      if (expired) {
        bucket = { count: 0, windowStart: nowMs }
      }
      const remaining = limit - bucket.count
      return remaining > 0 ? remaining : 0
    },

    reset(key: string): void {
      entries.delete(key)
    }
  }
}

