export function createEventEmitter() {
  type Listener = (...args: any[]) => any;
  interface ListenerEntry {
    fn: Listener;
    once: boolean;
  }

  const events = new Map<string, ListenerEntry[]>();

  function get(event: string): ListenerEntry[] {
    let list = events.get(event);
    if (!list) {
      list = [];
      events.set(event, list);
    }
    return list;
  }

  function on(event: string, listener: Listener): number {
    get(event).push({ fn: listener, once: false });
    return get(event).length;
  }

  function once(event: string, listener: Listener): number {
    get(event).push({ fn: listener, once: true });
    return get(event).length;
  }

  function off(event: string, listener: Listener): boolean {
    const list = get(event);
    for (let i = 0; i < list.length; i++) {
      if (list[i].fn === listener) {
        list.splice(i, 1);
        return true;
      }
    }
    return false;
  }

  function emit(event: string, payload?: any): any[] {
    const list = get(event);
    const results: any[] = [];
    for (const entry of list) {
      const result = entry.fn(payload);
      results.push(result);
      if (entry.once) {
        const idx = list.indexOf(entry);
        if (idx !== -1) list.splice(idx, 1);
      }
    }
    return results;
  }

  function listenerCount(event: string): number {
    return get(event).length;
  }

  return { on, once, off, emit, listenerCount };
}

