    const wrapper = (payload: unknown) => {
      listener(payload);
      off(event, listener);
    };
    return on(event, wrapper);
  };
  const off = (event: string, listener: Listener): boolean => {
    const arr = listeners.get(event);
    if (!arr) return false;
    for (let i = 0; i < arr.length; i++) {
      const entry = arr[i];
      if (entry.fn === listener) {
        arr.splice(i, 1);
        if (arr.length === 0) listeners.delete(event);
        return true;
      }
    }
    return false;
  };
  const emit = (event: string, payload: unknown): unknown[] => {
    const arr = listeners.get(event) ?? [];
    const results: unknown[] = [];
    for (const entry of arr) {
