export function createRateLimiter() {
  const state = new Map<string, {windowStart: number; count: number}>();
  const WINDOW = 1000;
  const LIMIT = 3;
  const getWindowStart = (now: number): number => Math.floor(now / WINDOW) * WINDOW;
  return {
    allow(key: string, nowMs: number): boolean {
      const winStart = getWindowStart(nowMs);
      const entry = state.get(key);
      if (!entry || entry.windowStart !== winStart) {
        state.set(key, {windowStart: winStart, count: 0});
      }
      const ent = state.get(key)!;
      if (ent.count < LIMIT) {
        ent.count += 1;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const winStart = getWindowStart(nowMs);
      const entry = state.get(key);
      let count = 0;
      if (entry && entry.windowStart === winStart) {
        count = entry.count;
      }
      const remaining = LIMIT - count;
      return remaining > 0 ? remaining : 0;
    },
    reset(key: string): void {
      state.delete(key);
    }
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const storage = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const WINDOW_MS = 1000;
      const LIMIT = 3;
      let state = storage.get(key);
      if (!state || nowMs - state.windowStart >= WINDOW_MS) {
        const windowStart = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;
        state = { windowStart, count: 0 };
        storage.set(key, state);
      }
      if (state.count < LIMIT) {
        state.count++;
        storage.set(key, state);
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const LIMIT = 3;
      const state = storage.get(key);
      if (!state) {
        return LIMIT;
      }
      if (nowMs - state.windowStart >= 1000) {
        return LIMIT;
      }
      return Math.max(0, LIMIT - state.count);
    },
    reset(key: string): void {
      storage.delete(key);
    }
  };
}

