export function createTtlCache(): { set(key: string, value: unknown, nowMs: number, ttlMs?: number): void; get(key: string, nowMs: number): unknown; has(key: string, nowMs: number): boolean; delete(key: string): boolean; size(nowMs: number): number; clear(): void; } {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs) {
      const ttl = ttlMs !== undefined ? ttlMs : 1000;
      cache.set(key, { value, expiresAt: nowMs + ttl });
    },
    get(key, nowMs) {
      const entry = cache.get(key);
      return entry?.expiresAt > nowMs ? entry.value : undefined;
    },
    has(key, nowMs) {
      const entry = cache.get(key);
      return !!entry && entry.expiresAt > nowMs;
    },
    delete(key) {
      return cache.delete(key);
    },
    size(nowMs) {
      return Array.from(cache.entries()).filter(([, e]) => e.expiresAt > nowMs).length;
    },
    clear() {
      cache.clear();
    },
  };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}
export function createTtlCache(): TtlCache {
  class _TTLCache implements TtlCache {
    private store = new Map<string, {value: unknown; expiresAt: number}>;
    private defaultTTL = 1000;
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs ?? this.defaultTTL;
      if (ttl === 0) {
        this.store.delete(key);
        return;
      }
      this.store.set(key, {value, expiresAt: nowMs + ttl});
    }
    get(key: string, nowMs: number): unknown {
      const entry = this.store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        this.store.delete(key);
        return undefined;
      }
      return entry.value;
    }
    has(key: string, nowMs: number): boolean {
      const entry = this.store.get(key);
      return !!entry && nowMs < entry.expiresAt;
    }
    delete(key: string): boolean {
      return this.store.delete(key);
    }
    size(nowMs: number): number {
      let count = 0;
      for (const {expiresAt} of this.store.values()) {
        if (nowMs < expiresAt) count++;
      }
      return count;
    }
    clear(): void {
      this.store.clear();
    }
  }
  return new _TTLCache();
}

