export function createEventEmitter(): EventEmitter {
  const events: Map<string, Listener[]> = new Map();

  function on(event: string, listener: Listener): number {
    if (!events.has(event)) {
      events.set(event, []);
    }
    events.get(event)!.push(listener);
    return events.get(event)!.length;
  }

  function once(event: string, listener: Listener): number {
    const wrappedListener = (...args: unknown[]) => {
      try {
        const result = listener(...args);
        off(event, wrappedListener);
        return result;
      } catch (error) {
        throw error;
      }
    };
    on(event, wrappedListener);
    return events.get(event)!.length;
  }

  function off(event: string, listener?: Listener): boolean {
    if (!events.has(event)) {
      return false;
    }
    const listeners = events.get(event)!;
    if (listener === undefined) {
      events.delete(event);
      return true;
    }
    const newListeners = listeners.filter(l => l !== listener);
    if (listeners.length !== newListeners.length) {
      events.set(event, newListeners);
      return true;
    }
    return false;
  }

  function emit(event: string, payload: unknown): unknown[] {
    const results: unknown[] = [];
    const listeners = events.get(event) || [];
    for (const listener of listeners) {
      results.push(listener(payload));
    }
    return results;
  }

  function listenerCount(event: string): number {
    return events.has(event) ? events.get(event)!.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener?: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}
