export function createTtlCache(): TtlCache {
  const entries: Record<string, { value: unknown; ttlMs: number }> = {};

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      ttlMs = ttlMs ?? 1000;
      entries[key] = { value, ttlMs };
    },
    get(key: string, nowMs: number): unknown {
      const entry = this.has(key, nowMs);
      return entry ? entries[key].value : undefined;
    },
    has(key: string, nowMs: number): boolean {
      if (!entries.hasOwnProperty(key)) return false;

      const { ttlMs } = entries[key];
      const isExpired = nowMs >= (ttlMs ? (entries[key].lastUpdatedMs ?? nowMs) + ttlMs : 0);
      return !isExpired;
    },
    delete(key: string): boolean {
      if (!entries.hasOwnProperty(key)) return false;
      delete entries[key];
      return true;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of Object.entries(entries)) {
        const isExpired = this.has(key, nowMs);
        if (isExpired) {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      entries = {};
    },
  };
}
