export function createEventEmitter(): EventEmitter {
  const listeners: Map<string, Set<Listener>> = new Map()

  class CustomEventEmitter implements EventEmitter {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, new Set())
      }
      listeners.get(event)?.add(listener)
      return this.listenerCount(event)
    }

    once(event: string, listener: Listener): number {
      const wrapper = (...args) => {
        try {
          listener(...args)
        } finally {
          this.off(event, wrapper)
        }
      }
      wrapper._listener = listener
      this.on(event, wrapper as any)
      return this.listenerCount(event)
    }

    off(event: string, listener?: Listener): boolean {
      const storedListeners = listeners.get(event)
      if (!storedListeners) return false

      if (listener !== undefined && storedListeners.has(listener)) {
        storedListeners.delete(listener)
        return true
      }
      // Remove all listeners for the event if no specific listener is provided
      listeners.delete(event)
      return !listeners.get(event)
    }

    emit(event: string, payload: unknown): unknown[] {
      const emissions: unknown[] = []
      const storedListeners = listeners.get(event) || new Set()
      for (const listener of storedListeners) {
        emissions.push(listener(payload))
      }
      return emissions
    }

    listenerCount(event: string): number {
      const listenersSet = listeners.get(event)
      if (!listenersSet) return 0
      return listenersSet.size
    }
  }

  return new CustomEventEmitter()
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener?: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}
