import { createRateLimiter } from './createRateLimiter';

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const rates: Map<string, { lastReset: number; usageCount: number }> = new Map();

  return {
    allow(key: string, nowMs: number): boolean {
      if (!rates.has(key) || (nowMs - rates.get(key)?.lastReset ?? windowMs) >= windowMs) {
        resetKey(key);
      }
      const currentUsage = rates.get(key)?.usageCount;
      return currentUsage < limit ? incrementAndReturn(true, key) : false;
    },
    remaining(key: string, nowMs: number): number {
      if (!rates.has(key) || (nowMs - rates.get(key)?.lastReset ?? windowMs) >= windowMs) {
        resetKey(key);
      }
      return Math.max(0, limit - (rates.get(key)?.usageCount ?? 0));
    },
    reset(key: string): void {
      rates.delete(key);
    },
  };

  function incrementAndReturn(value: boolean, key: string): boolean {
    const current = { lastReset: Date.now(), usageCount: 0 };
    const currentValue = { ...rates.get(key), usageCount: (rates.get(key)?.usageCount ?? 0) + 1 } || current;
    rates.set(key, currentValue);
    return value;
  }

  function resetKey(key: string): void {
    rates.set(key, { lastReset: Date.now(), usageCount: 0 });
  }
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
