export function createTodoApp(): TodoApp {
  let nextId = 1;
  const todos: Record<number, Todo> = {};

  function addTodo(text: string): Todo {
    const todo = { id: nextId, text, completed: false };
    todos[nextId] = todo;
    nextId++;
    return todo;
  }

  function getTodo(id: number): Todo | undefined {
    return todos[id];
  }

  function toggleTodo(id: number): void {
    if (todos[id]) {
      todos[id].completed = !todos[id].completed;
    }
  }

  function deleteTodo(id: number): boolean {
    const todo = todos[id];
    if (!todo) {
      return false;
    }
    delete todos[id];
    return true;
  }

  function listTodos(): Todo[] {
    return Object.values(todos);
  }

  function listCompleted(): Todo[] {
    return Object.values(todos).filter(todo => todo.completed);
  }

  function listPending(): Todo[] {
    return Object.values(todos).filter(todo => !todo.completed);
  }

  function clearCompleted(): void {
    const completedIds = Object.keys(todos)
      .map(Number)
      .filter(id => todos[id]!.completed);

    for (const id of completedIds) {
      delete todos[id];
    }
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}

