export function createTtlCache(): TtlCache {
  const entries = new Map<string, { value: unknown; expiresAt: number }>();

  class Cache implements TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      if (typeof entries === "undefined") {
        throw new Error("entries must be defined");
      }
      const expiresAt = ttlMs ? Math.max(nowMs, nowMs + ttlMs) : nowMs;
      entries.set(key, { value, expiresAt });
    }

    get(key: string, nowMs: number): unknown {
      if (typeof entries === "undefined") {
        throw new Error("entries must be defined");
      }
      const entry = entries.get(key);
      return this.isExpired(entry, nowMs) ? undefined : entry?.value;
    }

    has(key: string, nowMs: number): boolean {
      if (typeof entries === "undefined") {
        throw new Error("entries must be defined");
      }
      const entry = entries.get(key);
      return !this.isExpired(entry, nowMs);
    }

    delete(key: string): boolean {
      if (typeof entries === "undefined") {
        throw new Error("entries must be defined");
      }
      const deleted = entries.delete(key);
      return !!deleted;
    }

    size(nowMs: number): number {
      if (typeof entries === "undefined") {
        throw new Error("entries must be defined");
      }
      let count = 0;
      for (const entry of entries.values()) {
        if (!this.isExpired(entry, nowMs)) {
          ++count;
        }
      }
      return count;
    }

    clear(): void {
      if (typeof entries === "undefined") {
        throw new Error("entries must be defined");
      }
      entries.clear();
    }

    private isExpired(entry: any, nowMs: number): boolean {
      return entry?.expiresAt <= nowMs || typeof entry === "undefined";
    }
  }

  const ttlCache = new Cache();
  return ttlCache;
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}
