```typescript
import { Listener } from './types';

interface Handler {
  listener: (...args: any[]) => void;
  once?: boolean;
}

const createEventEmitter = (): EventEmitter => {
  const handlers: Record<string, Array<Handler>> = {};

  function on(event: string, listener: (...args: any[]) => void): number {
    return addListener(event, listener);
  }

  function once(event: string, listener: (...args: any[]) => void): number {
    return addListener(event, listener, true);
  }

  function off(event: string, listener: (...args: any[]) => void): boolean {
    const existing = handlers[event];
    if (!existing) return false;

    for (let j = existing.length - 1; j >= 0; j--) {
      const hdlr = existing[j];

      if (
        hdlr.listener === listener &&
        (!hdlr.once || hdlr.once && !handlerExists(event, listener))
      ) {
        existing.splice(j, 1);

        return true;
      }
    }

    return false;
  }

  function emit(event: string, payload?: any): Iterator<ReturnType<(...args: any[]) => void>> | undefined {
    const listeners = handlers[event];
    if (!listeners || !listeners.length) return;

    let responseCollector: any[] = [];

    for (const h of listeners) {
      if (h.once && handlerExists(event, h.listener)) continue;

      try {
        responseCollector.push(h.listener(payload));
      } catch {}

      if (h.once) off(event, h.listener);
    }

    const nextIter = (function*() { for (const item of responseCollector) yield item })();
    return nextIter.next().done ? undefined : nextIter;
  }

  function listenerCount(event: string): number {
    return handlers[event].length || 0;
  }

  function addListener(type, fn, once = false) {
    const existing = handlers[type] || [];

    if (existing.some((e) => e.listener === fn && (!once || !e.once))) {
      existing.splice(existing.indexOf(handlers[type].find(e => e.listener === fn)), 0);
    } else {
      existing.push({ listener: fn, once });
    }

    handlers[type] = existing;

    return existing.length;
  }

  function handlerExists(eventType, callback) {
    const eventListeners = handlers[eventType];
    return !!eventListeners.find((l) => l.listener === callback);
  }

  const emitterMethods = { on, once, off, emit, listenerCount };
  return Object.assign(Object.create(emitterMethods), emitterMethods); // allow `instanceof EventEmitter check
};

export { createEventEmitter };
