export function createRateLimiter() {
  const limits = new Map<string, { until: number; remaining: number }>();

  return {
    allow(key, nowMs) {
      if (!this.remaining(key, nowMs)) {
        return false;
      }
      const info = this.getInfo(key);
      --info.remaining;
      return true;
    },
    remaining(key, _nowMs) {
      const info = this.getInfo(key);
      const untilNextReset = Math.max(info.until - Date.now(), 0);
      if (untilNextReset <= 0) {
        // Reset before next call.
        info.remaining = 3;
        info.until = nowMs + 1000;
      }
      return Math.min(3, info.remaining);
    },
    reset(key) {
      const oldInfo = this.limits.get(key);
      if (oldInfo == null) {
        return;
      }
      // Zero remaining for that key, even when it hasn't yet expired.
      oldInfo.remaining = 0;
    },
    getInfo(key) {
      let info: { until: number; remaining: number } = this.limits.get(key);
      if (info == undefined) {
        info = { until: Date.now(), remaining: 3 };
        this.limits.set(key, info);
      }
      return info;
    },
  };
}
