export function createRateLimiter(): RateLimiter {
  const windowMs = 1000;
  const limit = 3;
  const windows: Map<string, { count: number; resetAt: number }> = new Map();

  return {
    allow(key, nowMs) {
      let windowInfo = windows.get(key);
      if (!windowInfo || nowMs - windowInfo.resetAt >= windowMs) {
        windowInfo = { count: limit, resetAt: nowMs };
        windows.set(key, windowInfo);
      }
      if (windowInfo.count > 0) {
        windowInfo.count--;
      }
      return windowInfo.count >= 0;
    },
    remaining(key, nowMs) {
      const windowInfo = windows.get(key);
      if (!windowInfo || nowMs - windowInfo.resetAt >= windowMs) {
        return limit;
      }
      return Math.max(0, windowInfo.count);
    },
    reset(key) {
