export function createEventEmitter(): {
    on(event: string, listener: (...args: any[]) => any): number;
    once(event: string, listener: (...args: any[]) => any): number;
    off(event: string, listener: (...args: any[]) => any): boolean;
    emit(event: string, payload?: any[]): any[];
    listenerCount(event: string): number;
} {
    const listeners: { [key: string]: ((...args: any[]) => any)[] } = {};

    return {
        on(event: string, listener: (...args: any[]) => any): number {
            if (!listeners[event]) {
                listeners[event] = [];
            }
            listeners[event].push(listener);
            return listeners[event].length;
        },
        once(event: string, listener: (...args: any[]) => any): number {
            const onceListener = (payload: any) => {
                listener(payload);
                this.off(event, onceListener);
            };
            return this.on(event, onceListener);
        },
        off(event: string, listener: (...args: any[]) => any): boolean {
            if (!listeners[event]) {
                return false;
            }
            const index = listeners[event].indexOf(listener);
            if (index === -1) {
                return false;
            }
            listeners[event].splice(index, 1);
            return true;
        },
        emit(event: string, payload?: any[]): any[] {
            if (!listeners[event]) {
                return [];
            }
            const results = [];
            for (const listener of listeners[event]) {
                results.push(listener(payload));
            }
            return results;
        },
        listenerCount(event: string): number {
            return listeners[event] ? listeners[event].length : 0;
        }
    };
}
