  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
      cache[key] = [value, nowMs + ttlMs];
    },
    get(key: string, nowMs: number): unknown {
      if (key in cache) {
        const [value, expiresAt] = cache[key];
        if (nowMs >= expiresAt) {
          delete cache[key];
          return undefined;
        }
        return value;
      }
      return undefined;
    },
    has(key: string, nowMs: number): boolean {
      if (key in cache) {
        const [value, expiresAt] = cache[key];
        return nowMs < expiresAt;
