    delete(key: string): boolean {
      if (key in cache) {
        delete cache[key];
        return true;
      }
      return false;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const key of Object.keys(cache)) {
        const [value, expiresAt] = cache[key];
        if (nowMs < expiresAt) count++;
      }
      return count;
    },
