      memoryValue += currentValue;
    }
    return this as unknown as Calculator;
  };

  return {
    add,
    subtract,
    multiply,
    divide,
    clear,
    result,
    memoryStore,
    memoryRecall,
    memoryClear,
    memoryAdd
  };
