export function createRateLimiter() {
    const timestamps = new Map<string, number[]>();

    return {
        allow(key: string, nowMs: number) {
            let currentWindowTimestamps = timestamps.get(key);
            if (!currentWindowTimestamps) {
                currentWindowTimestamps = [nowMs];
                timestamps.set(key, currentWindowTimestamps);
                return true;
            }

            const lastTimestamp = currentWindowTimestamps[currentWindowTimestamps.length - 1];
            if (lastTimestamp && nowMs < lastTimestamp + 1000 / 3) {
                return false;
            }

            for (let i = 0; i < currentWindowTimestamps.length; ++i) {
                const timestamp = currentWindowTimestamps[i];
                if (!timestamp || nowMs - timestamp >= 1000) {
                    currentWindowTimestamps[i] = nowMs;
                    return true;
                }
            }

            return false;
        },

        remaining(key: string, nowMs: number): number {
            const currentWindowTimestamps = timestamps.get(key);
            if (!currentWindowTimestamps) {
                return 3;
            }

            let remainingCount = 0;
            for (let timestamp of currentWindowTimestamps) {
                if (timestamp && nowMs - timestamp < 1000 / 3) {
                    ++remainingCount;
                } else {
                    break;
                }
            }

            const fullWindowsElapsed = Math.floor((nowMs - currentWindowTimestamps[0]) / 1000);
            remainingCount += 3 * fullWindowsElapsed;

            return Math.min(3, remainingCount);
        },

        reset(key: string) {
            timestamps.delete(key);
            timestamps.set(key, [Date.now()]);
        }
    };
}
