export function createRateLimiter(): RateLimiter {
  const state: Record<string, { windowStartMs: number; count: number }> = {};

  function allow(key: string, nowMs: number): boolean {
    if (!state[key]) {
      state[key] = { windowStartMs: nowMs, count: 0 };
    }

    const { windowStartMs, count } = state[key];

    boundaryResetRule(nowMs);

    if (count >= 3) return false;
    state[key].count += 1;

    return true;
  }

  function remaining(key: string, nowMs: number): number {
    if (!state[key]) return 0;

    const { windowStartMs } = state[key];

    boundaryResetRule(nowMs);

    return Math.min(3 - state[key].count, (nowMs - windowStartMs) / 1000);
  }

  function reset(key: string): void {
    if (!state[key]) return;

    delete state[key];
  }

  function boundaryResetRule(nowMs: number): void {
    for (const key of Object.keys(state)) {
      const { windowStartMs } = state[key];

      if (nowMs - windowStartMs >= 1000) state[key] = { windowStartMs: nowMs, count: 0 };
    }
  }

  return {
    allow,
    remaining,
    reset
  };
}
