export function createTtlCache(): TtlCache {
  const items: { [key: string]: { value: unknown; expiresAt: number } } = {};

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs = 1000): void {
      if (value === undefined) {
        delete items[key];
      } else {
        items[key] = {
          value,
          expiresAt: nowMs + ttlMs
        };
      }
    },
    get(key: string, nowMs: number): unknown {
      const item = items[key];
      return item ? (!item.expiresAt || nowMs < item.expiresAt) ? item.value : undefined : undefined;
    },
    has(key: string, nowMs: number): boolean {
      return this.get(key, nowMs) !== undefined;
    },
    delete(key: string): boolean {
      const result = this.has(key);
      if (result) {
        delete items[key];
      }
      return result;
    },
    size(nowMs: number): number {
      return Object.values(items).filter(item => item.expiresAt > nowMs || !item.expiresAt).length;
    },
    clear(): void {
      items = {};
    }
  };
}
