export function createEventEmitter() {
  const listeners = new Map<string, Listener[]>();

  return {
    on(event: string, listener: Listener): number {
      const existingListeners = listeners.get(event) || [];
      existingListeners.push(listener);
      listeners.set(event, existingListeners);
      return existingListeners.length;
    },

    once(event: string, listener: Listener): number {
      const existingListeners = listeners.get(event) || [];
      existingListeners.push(listener);
      listeners.set(event, existingListeners);
      return existingListeners.length;
    },

    off(event: string, listener: Listener): boolean {
      const listenersArray = listeners.get(event);
      if (!listenersArray) return false;
      const index = listenersArray.indexOf(listener);
      if (index === -1) return false;
      listenersArray.splice(index, 1);
      listeners.set(event, listenersArray);
      return true;
    },

    emit(event: string, payload: unknown): unknown[] {
      const listenersArray = listeners.get(event);
      if (!listenersArray) return [];
      const results: unknown[] = [];
      for (const listener of listenersArray) {
        results.push(listener(payload));
      }
      return results;
    },

    listenerCount(event: string): number {
      const listenersArray = listeners.get(event);
      return listenersArray ? listenersArray.length : 0;
    }
  };
}
