      if (this.count < this.limit) {
        this.count++;
        this.remaining = this.limit - this.count;
        return true;
      }
      return false;
    },
    remaining: (key: string, nowMs: number): number => {
      if (nowMs - this.windowStart >= this.windowMs) {
        this.windowStart = nowMs;
        this.count = 0;
        this.remaining = this.limit;
      }
      return this.remaining;
    },
    reset: (key: string) => {
      this.windowStart = nowMs;
      this.count = 0;
      this.remaining = this.limit;
    }
  };
  return rateLimiter;
}
