```ts
export function createEventEmitter(): EventEmitter {

  interface EventEmitter {
    on(event: string, listener: Listener): number
    once(event: string, listener: Listener): number
    off(event: string, listener: Listener): boolean
    emit(event: string, payload: unknown): unknown[]
    listenerCount(event: string): number
  }

  class EventEmitterImpl {
    private listeners: Map<string, Listener[]> = new Map();
    private listenerCount: Map<string, number> = new Map();

    on(event: string, listener: Listener): number {
      const count = this.listenerCount.get(event) || 0;
      this.listeners.set(event, [...this.listeners.get(event) || [], listener]);
      this.listenerCount.set(event, count + 1);
      return count + 1;
    }

    once(event: string, listener: Listener): number {
      const count = this.listenerCount.get(event) || 0;
      this.listeners.set(event, [...this.listeners.get(event) || [], listener]);
      this.listenerCount.set(event, count + 1);
      return count + 1;
    }

    off(event: string, listener: Listener): boolean {
      const listeners = this.listeners.get(event);
      if (!listeners) return false;
      const index = listeners.findIndex(l => l === listener);
      if (index === -1) return false;
      listeners.splice(index, 1);
      this.listenerCount.set(event, this.listenerCount.get(event) - 1);
      return true;
    }

    emit(event: string, payload: unknown): unknown[] {
      const listeners = this.listeners.get(event);
      if (!listeners) return [];
      const results: unknown[] = [];
      for (const listener of listeners) {
        results.push(listener(payload));
      }
      return results;
    }

    listenerCount(event: string): number {
      return this.listenerCount.get(event) || 0;
    }
  }

  return new EventEmitterImpl();
}
