// event-emitter.ts

export const createEventEmitter = () => ({
  on(event: string, listener: (payload: any) => void) {
    if (!listeners[event]) {
      listeners[event] = [{ listener, count: 0 }];
    }
    listeners[event].push({ listener, count: listeners[event].length });
    return listeners[event].length;
  },
  once(event: string, listener: (payload: any) => void) {
    if (!listeners[event]) {
      listeners[event] = [{ listener, count: 0 }];
    }
    listeners[event].push({ listener, count: listeners[event].length, isOneTime: true });
    return listeners[event].length;
  },
  off(event: string, listener: (payload: any) => void) {
    if (!listeners[event]) return false;
    const index = listeners[event].findIndex(l => l.listener === listener && l.isOneTime === false);
    if (index === -1) return false;
    listeners[event].splice(index, 1);
    return true;
  },
  emit(event: string, payload: any) {
    if (!listeners[event]) return [];
    const listenersForEvent = listeners[event];
    const results = [];
    for (const listener of listenersForEvent) {
      results.push(listener.payload(payload));
    }
    return results;
  },
  listenerCount(event: string) {
    return listeners[event]?.length || 0;
  },
  // Helper to manage listeners
  _getListeners(event: string) {
    return listeners[event] || [];
  }
});

const listeners: Record<string, Array<{ listener: (payload: any) => void, count: number, isOneTime: boolean }>> = {};
