export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const rateLimiter: Record<string, RateLimiterState> = {};

  function RateLimiterState() {
    this.timestamps = [];
    this.currentWindowStart = 0;
  }

  return {
    allow: (key: string, nowMs: number): boolean => {
      if (!rateLimiter[key]) {
        rateLimiter[key] = new RateLimiterState();
      }
      const state = rateLimiter[key];
      const lastTimestamp = state.timestamps[state.timestamps.length - 1];
      if (!lastTimestamp || nowMs - lastTimestamp > windowMs) {
        state.currentWindowStart = nowMs;
        state.timestamps = [];
      }
      const index = state.timestamps.indexOf(nowMs);
      if (index === -1) {
        state.timestamps.push(nowMs);
        return state.timestamps.length <= limit;
      }
      const windowEnd = state.currentWindowStart + windowMs;
      const windowStart = state.timestamps[index];
      if (nowMs - windowStart >= windowEnd) {
        state.currentWindowStart = nowMs;
        state.timestamps = [];
      }
      return state.timestamps.length <= limit;
    },
    remaining: (key: string, nowMs: number): number => {
      if (!rateLimiter[key]) {
        return 0;
      }
      const state = rateLimiter[key];
      const lastTimestamp = state.timestamps[state.timestamps.length - 1];
      if (!lastTimestamp || nowMs - lastTimestamp > windowMs) {
        return state.timestamps.length;
      }
      const index = state.timestamps.indexOf(nowMs);
      if (index === -1) {
        return state.timestamps.length;
      }
      const windowEnd = state.currentWindowStart + windowMs;
      const windowStart = state.timestamps[index];
      if (nowMs - windowStart >= windowEnd) {
        return state.timestamps.length;
      }
      return state.timestamps.length - index;
    },
    reset: (key: string) => {
      if (!rateLimiter[key]) {
        return;
      }
      rateLimiter[key].timestamps = [];
      rateLimiter[key].currentWindowStart = 0;
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
