function createEventEmitter() {
  const listeners = new Map<string, Array<{ listener: Function; once: boolean }>>();

  return {
    on(event: string, listener: Function): number {
      let list = listeners.get(event) || [];
      list.push({ listener, once: false });
      listeners.set(event, list);
      return list.length;
    },
    once(event: string, listener: Function): number {
      let list = listeners.get(event) || [];
      list.push({ listener, once: true });
      listeners.set(event, list);
      return list.length;
    },
    off(event: string, listener: Function): boolean {
      const list = listeners.get(event);
      if (!list) return false;
      for (let i = 0; i < list.length; i++) {
        if (list[i].listener === listener) {
          list.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event: string, payload: any): any[] {
      const list = listeners.get(event) || [];
      const copy = [...list];
      const results: any[] = [];
      for (const entry of copy) {
        const result = entry.listener(payload);
        results.push(result);
        if (entry.once) {
          const index = list.indexOf(entry);
          if (index !== -1) {
            list.splice(index, 1);
          }
        }
      }
      return results;
    },
    listenerCount(event: string): number {
      const list = listeners.get(event) || [];
      return list.length;
    },
  };
