export function createEventEmitter() {
  const events = new Map<string, { callback: Function; once: boolean }[]>();

  return {
    on(event: string, listener: Function): number {
      if (!events.has(event)) {
        events.set(event, []);
      }
      events.get(event)!.push({ callback: listener, once: false });
      return events.get(event)!.length;
    },
    once(event: string, listener: Function): number {
      if (!events.has(event)) {
        events.set(event, []);
      }
      events.get(event)!.push({ callback: listener, once: true });
      return events.get(event)!.length;
    },
    off(event: string, listener: Function): boolean {
      const listeners = events.get(event);
      if (!listeners) {
        return false;
      }
      for (let i = 0; i < listeners.length; i++) {
        if (listeners[i].callback === listener) {
          listeners.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event: string, payload: any): any[] {
      const listeners = events.get(event) || [];
      const results: any[] = [];
      const toRemove: number[] = [];
      for (let i = 0; i < listeners.length; i++) {
        const listener = listeners[i];
        const result = listener.callback(payload);
        results.push(result);
        if (listener.once) {
          toRemove.push(i);
        }
      }
      for (const index of toRemove.reverse()) {
        listeners.splice(index, 1);
      }
      return results;
    },
    listenerCount(event: string): number {
      return (events.get(event) || []).length;
    }
  };
