export function createRateLimiter(): RateLimiter {
  const map = new Map<string, { count: number; windowStart: number }>();
  const limit = 3;
  const windowMs = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      const now = nowMs;
      let state = map.get(key);
      if (!state) {
        state = { count: 0, windowStart: now };
        map.set(key, state);
      } else if (now - state.windowStart >= windowMs) {
        state.count = 0;
        state.windowStart = now;
      }

      if (state.count < limit) {
        state.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const now = nowMs;
      const state = map.get(key);
      if (!state) {
        return limit;
      } else if (now - state.windowStart >= windowMs) {
        state.count = 0;
        state.windowStart = now;
      }

      return Math.max(limit - state.count, 0);
    },
    reset(key: string): void {
      map.delete(key);
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
