export function createEventEmitter(): EventEmitter {
  const events: Record<string, Listener[]> = {};

  const instance = {
    on(event: string, listener: Listener): number {
      events[event] = events[event] || [];
      events[event].push(listener);
      return events[event].length;
    },
    once(event: string, listener: Listener): number {
      const wrapper = (payload: unknown) => {
        const result = listener(payload);
        const index = events[event]?.indexOf(wrapper);
        if (index >= 0) {
          events[event].splice(index, 1);
        }
        return result;
      };
      events[event] = events[event] || [];
      events[event].push(wrapper);
      return events[event].length;
    },
    off(event: string, listener: Listener): boolean {
      const listeners = events[event] || [];
      const index = listeners.indexOf(listener);
      if (index >= 0) {
        listeners.splice(index, 1);
        return true;
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      const listeners = events[event] || [];
      return listeners.map(listener => listener(payload));
    },
    listenerCount(event: string): number {
      return events[event] ? events[event].length : 0;
    }
  };

  return instance;
}

