export function createRateLimiter() {
  const state = new Map<string, { start: number; count: number }>();

  const allow = (key: string, nowMs: number) => {
    if (!state.has(key)) {
      state.set(key, { start: nowMs, count: 0 });
    }

    const entry = state.get(key);
    if (nowMs >= entry.start + 1000) {
      state.set(key, { start: nowMs, count: 0 });
    }

    if (entry.count < 3) {
      state.set(key, { start: entry.start, count: entry.count + 1 });
      return true;
    }
    return false;
  };

  const remaining = (key: string, nowMs: number) => {
    const entry = state.get(key);
    if (!entry) {
      return 3;
    }

    if (nowMs >= entry.start + 1000) {
      state.set(key, { start: nowMs, count: 0 });
    }

    return 3 - entry.count;
  };

  const reset = (key: string) => {
    state.set(key, { start: 0, count: 0 });
  };

  return { allow, remaining, reset };
}
