export function createEventEmitter() {
  const listeners = new Map<string, { fn: Function; once: boolean }[]>();

  return {
    on(event: string, listener: Function): number {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ fn: listener, once: false });
      return listeners.get(event)!.length;
    },
    once(event: string, listener: Function): number {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ fn: listener, once: true });
      return listeners.get(event)!.length;
    },
    off(event: string, listener: Function): boolean {
      const eventListeners = listeners.get(event);
      if (!eventListeners) return false;
      const index = eventListeners.findIndex(l => l.fn === listener);
      if (index === -1) return false;
      eventListeners.splice(index, 1);
      return true;
    },
    emit(event: string, payload: any): any[] {
      const eventListeners = listeners.get(event);
      if (!eventListeners) return [];
      const results = [];
      const listenersCopy = [...eventListeners];
      for (const listener of listenersCopy) {
        results.push(listener.fn(payload));
        if (listener.once) {
          const index = eventListeners.indexOf(listener);
          if (index !== -1) {
            eventListeners.splice(index, 1);
          }
        }
      }
      return results;
    },
    listenerCount(event: string): number {
      const eventListeners = listeners.get(event);
      return eventListeners ? eventListeners.length : 0;
    }
  };
}
