```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

class EventEmitterImpl implements EventEmitter {
  private events = new Map<string, {
    regular: Listener[];
    once: Listener[];
  }>();

  on(event: string, listener: Listener): number {
    if (!this.events.has(event)) {
      this.events.set(event, { regular: [], once: [] });
    }
    this.events.get(event)!.regular.push(listener);
    return this.events.get(event)!.regular.length;
  }

  once(event: string, listener: Listener): number {
    if (!this.events.has(event)) {
      this.events.set(event, { regular: [], once: [] });
    }
    this.events.get(event)!.once.push(listener);
    return this.events.get(event)!.once.length;
  }

  off(event: string, listener: Listener): boolean {
    const eventMap = this.events.get(event);
    if (!eventMap) return false;

    const idxRegular = eventMap.regular.indexOf(listener);
    if (idxRegular !== -1) {
      eventMap.regular.splice(idxRegular, 1);
      return true;
    }

    const idxOnce = eventMap.once.indexOf(listener);
    if (idxOnce !== -1) {
      eventMap.once.splice(idxOnce, 1);
      return true;
    }

    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    if (!this.events.has(event)) return [];

    const eventMap = this.events.get(event)!;
    const results: unknown[] = [];

    for (const listener of eventMap.regular) {
      results.push(listener(payload));
    }

    for (let i = 0; i < eventMap.once.length; i++) {
      const listener = eventMap.once[i];
      const result = listener(payload);
      results.push(result);
      eventMap.once.splice(i, 1);
    }

    return results;
  }

  listenerCount(event: string): number {
    return this.events.has(event)
      ? this.events.get(event)!.regular.length + this.events.get(event)!.once.length
      : 0;
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitterImpl();
}
