class TtlCache {
  private storage = new Map<string, { value: unknown; expiresAt: number }>();
  private defaultTtlMs = 1000;

  set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
    const expiration = nowMs + (ttlMs ?? this.defaultTtlMs);
    this.storage.set(key, { value, expiresAt: expiration });
  }

  get(key: string, nowMs: number) {
    const entry = this.storage.get(key);
    if (!entry) return undefined;
    if (nowMs >= entry.expiresAt) {
      this.storage.delete(key);
      return undefined;
    }
    return entry.value;
  }

  has(key: string, nowMs: number) {
    const entry = this.storage.get(key);
    if (!entry) return false;
    if (nowMs >= entry.expiresAt) {
      this.storage.delete(key);
      return false;
    }
    return true;
  }

  delete(key: string) {
    return this.storage.delete(key);
  }

  size(nowMs: number) {
    return Array.from(this.storage).reduce((count, [key, entry]) => {
      return nowMs < entry.expiresAt ? count + 1 : count;
    }, 0);
  }

  clear() {
    this.storage.clear();
  }
}

export function createTtlCache() {
  return new TtlCache();
}
