type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

class EventEmitter implements EventEmitter {
  private listeners = new Map<string, Array<{ listener: Listener; once: boolean }>>();

  on(event: string, listener: Listener): number {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event)!.push({ listener, once: false });
    return this.listeners.get(event)!.length;
  }

  once(event: string, listener: Listener): number {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event)!.push({ listener, once: true });
    return this.listeners.get(event)!.length;
  }

  off(event: string, listener: Listener): boolean {
    const eventListeners = this.listeners.get(event) || [];
    const index = eventListeners.findIndex(l => l.listener === listener);
    if (index !== -1) {
      eventListeners.splice(index, 1);
      return true;
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const eventListeners = this.listeners.get(event) || [];
    const results: unknown[] = [];
    for (let i = 0; i < eventListeners.length; i++) {
      const listener = eventListeners[i];
      if (listener.once) {
        results.push(listener.listener(payload));
        eventListeners.splice(i, 1);
        i = -1;
      } else {
        results.push(listener.listener(payload));
      }
    }
    return results;
  }

  listenerCount(event: string): number {
    return this.listeners.get(event) ? this.listeners.get(event).length : 0;
  }
}

export function createRateLimiter() {
  const rateLimiterMap = new Map<string, { windowStart: number; count: number }>();

  return {
    allow: (key: string, nowMs: number) => {
      const state = rateLimiterMap.get(key) || { windowStart: nowMs, count: 0 };
      const elapsed = nowMs - state.windowStart;
      if (elapsed >= 1000) {
        rateLimiterMap.set(key, { windowStart: nowMs, count: 1 });
        return true;
      }
      if (state.count < 3) {
        rateLimiterMap.set(key, { windowStart: state.windowStart, count: state.count + 1 });
        return true;
      }
      return false;
    },
    remaining: (key: string, nowMs: number) => {
      const state = rateLimiterMap.get(key) || { windowStart: nowMs, count: 0 };
      return Math.max(0, 3 - state.count);
    },
    reset: (key: string) => {
      rateLimiterMap.delete(key);
    }
  };
}

