const windowMs = 1000;
const limit = 3;

const rateLimiterMap = new Map<string, { startTime: number; count: number }>();

export function createRateLimiter(): RateLimiter {
  return {
    allow(key: string, nowMs: number): boolean {
      const state = rateLimiterMap.get(key);
      if (!state) {
        rateLimiterMap.set(key, { startTime: nowMs, count: 0 });
      }

      const windowElapsed = nowMs - state.startTime;
      if (windowElapsed >= windowMs) {
        rateLimiterMap.set(key, { startTime: nowMs, count: 0 });
      }

      state.count++;
      if (state.count > limit) {
        return false;
      }

      rateLimiterMap.set(key, { ...state });
      return true;
    },
    remaining(key: string, nowMs: number): number {
      const state = rateLimiterMap.get(key);
      if (!state) {
        return limit;
      }

      const windowElapsed = nowMs - state.startTime;
      if (windowElapsed >= windowMs) {
        rateLimiterMap.set(key, { startTime: nowMs, count: 0 });
      }

      return limit - state.count;
    },
    reset(key: string): void {
      rateLimiterMap.delete(key);
    }
  };
}
