export function createTtlCache() {
  const internalCache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => {
      const expiresAt = nowMs + (ttlMs ?? 1000);
      internalCache.set(key, { value, expiresAt });
    },
    get: (key: string, nowMs: number) => {
      const entry = internalCache.get(key);
      return entry && nowMs < entry.expiresAt ? entry.value : undefined;
    },
    has: (key: string, nowMs: number) => {
      const entry = internalCache.get(key);
      return !!entry && nowMs < entry.expiresAt;
    },
    delete: (key: string) => {
      return internalCache.delete(key);
    },
    size: (nowMs: number) => {
      return Array.from(internalCache).reduce(
        (count, [_, entry]) => count + (nowMs < entry.expiresAt ? 1 : 0),
        0
      );
    },
    clear: () => {
      internalCache.clear();
    },
  };
}
