export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      cache.set(key, { value, expiresAt: nowMs + ttlMs });
    },
    get(key, nowMs) {
      const entry = cache.get(key);
      return entry && nowMs < entry.expiresAt ? entry.value : undefined;
    },
    has(key, nowMs) {
      const entry = cache.get(key);
      return !!entry && nowMs < entry.expiresAt;
    },
    delete(key) {
      return cache.delete(key);
    },
    size(nowMs) {
      return Array.from(cache.values()).reduce(
        (count, { expiresAt }) => count + (nowMs < expiresAt ? 1 : 0),
        0
      );
    },
    clear() {
      cache.clear();
    }
  };
