export function createRateLimiter(nowMs: number): { allow: (key: string, nowMs: number) => boolean; remaining: (key: string, nowMs: number) => number; reset: (key: string) => void; } {
  const counts = new Map<string, number>();
  const windowDuration = 1000;

  return {
    allow: (key: string, nowMs: number): boolean => {
      if (counts.has(key)) {
        return nowMs >= windowDuration;
      }
      counts.set(key, (counts.get(key) || 0) + 1);
      return true;
    },

    remaining: (key: string, nowMs: number): number => {
      return counts.get(key) || 0;
    },

    reset: (key: string): void => {
      counts.delete(key);
    }
  };
}

