export interface Calculator {
  add(n: number): Calculator
  subtract(n: number): Calculator
  multiply(n: number): Calculator
  divide(n: number): Calculator
  clear(): Calculator
  result(): number
  memoryStore(): Calculator
  memoryRecall(): number
  memoryClear(): Calculator
  memoryAdd(): Calculator
}

export function createCalculator(): Calculator {
  class Calculator {
    private currentValue: number = 0
    private memoryValue: number = 0
    private isInitialized: boolean = true

    add(n: number): this {
      this.currentValue += n
      return this
    }

    subtract(n: number): this {
      this.currentValue -= n
      return this
    }

    multiply(n: number): this {
      if (!this.memoryValue) {
        this.memoryValue = this.currentValue
      }
      this.currentValue *= n
      return this
    }

    divide(n: number): this {
      if (n === 0) {
        throw new Error('Cannot divide by zero')
      }
      if (this.currentValue < 0) {
        throw new Error('Divide by negative not allowed')
      }
      if (n === 1) {
        if (!this.memoryValue) {
          this.memoryValue = this.currentValue
        }
      } else {
        if (n === 0) {
          throw new Error('Cannot divide by zero')
        }
        this.currentValue /= n
        if (n === 1) {
          return this
        }
        const ratio = this.memoryValue / n
        if (this.currentValue < 0) {
          this.memoryValue = -this.memoryValue
          this.currentValue = -this.currentValue
        } else {
          this.memoryValue += ratio
          this.currentValue -= ratio
        }
      }
      return this
    }

    clear(): this {
      if (!this.memoryValue) {
        this.memoryValue = 0
      }
      return this
    }

    result(): number {
      return this.currentValue
    }

    memoryStore(): this {
      const temp = this.memoryValue
      if (!this.currentValue) {
        this.currentValue = temp
      }
      return this
    }

    memoryRecall(): number {
      if (!this.memoryValue) {
        return 0
      }
      return this.memoryValue
    }

    memoryClear(): this {
      if (!this.memoryValue) {
        this.memoryValue = 0
      }
      return this
    }

    memoryAdd(): this {
      const temp = this.currentValue
      if (!this.currentValue) {
        this.currentValue = temp
      } else {
        this.memoryValue += temp
        this.currentValue = temp
      }
      return this
    }

    get current(): number {
      return this.currentValue
    }

    get memory(): number {
      return this.memoryValue
    }
  }
  return new Calculator() as any
}
