export function createTtlCache(): TtlCache {
  class TllCache {
    private cache: Map<string, unknown> = new Map()

    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      this.cache.set(key, value)
      if (this.cache.size > 0) {
        const expiration = nowMs + ttlMs * 1000
        if (nowMs === expiration) {
          this.cache.delete(key)
        }
      }
    }

    get(key: string, nowMs: number): unknown {
      let value = this.cache.get(key)

      if (value === undefined) {
        // No expiration yet
        value = {}
      } else {
        const expiration = nowMs + ttlMs * 1000
        if (nowMs >= expiration) {
          this.cache.delete(key)
          return value
        }
      }
    }

    has(key: string, nowMs: number): boolean {
      const value = this.cache.get(key)

      if (value === undefined) {
        return false
      }

      if (nowMs >= value.expiresAt) {
        this.cache.delete(key)
        return false
      }
      return true
    }

    delete(key: string): boolean {
      const value = this.cache.get(key)
      this.cache.delete(key)
      return true
    }

    size(nowMs: number): number {
      const value = this.cache.length
      return value
    }

    clear(): void {
      this.cache.clear()
    }
  }

  return new TllCache()
}
