interface RateLimiterState {
  windowStartMs: number;
  count: number;
}

export function createRateLimiter(): {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
} {
  const LIMIT = 3;
  const WINDOW_SIZE_MS = 1000;
  const store = new Map<string, RateLimiterState>();

  function allow(key: string, nowMs: number): boolean {
    let state = store.get(key);

    if (!state) {
      state = { windowStartMs: nowMs, count: 1 };
      store.set(key, state);
      return true;
    }

    if (nowMs >= state.windowStartMs + WINDOW_SIZE_MS) {
      state.windowStartMs = nowMs;
      state.count = 1;
      return true;
    }

    if (state.count < LIMIT) {
      state.count++;
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const state = store.get(key);

    if (!state) {
      return LIMIT;
    }

    if (nowMs >= state.windowStartMs + WINDOW_SIZE_MS) {
      return LIMIT;
    }

    return Math.max(0, LIMIT - state.count);
  }

  function reset(key: string): void {
    store.delete(key);
  }

  return { allow, remaining, reset };
}
