type Listener = (payload: unknown) => unknown;
type EventEntry = {
  listener: Listener;
  once: boolean;
};

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, EventEntry[]>();

  function on(event: string, listener: Listener): number {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const entries = listeners.get(event)!;
    entries.push({ listener, once: false });
    return entries.length;
  }

  function once(event: string, listener: Listener): number {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const entries = listeners.get(event)!;
    entries.push({ listener, once: true });
    return entries.length;
  }

  function off(event: string, listener: Listener): boolean {
    const entries = listeners.get(event);
    if (!entries) return false;

    const index = entries.findIndex(entry => entry.listener === listener);
    if (index === -1) return false;

    entries.splice(index, 1);
    if (entries.length === 0) {
      listeners.delete(event);
    }
    return true;
  }

  function emit(event: string, payload: unknown): unknown[] {
    const entries = listeners.get(event);
    if (!entries) return [];

    const results: unknown[] = [];
    const toRemove: boolean[] = [];

    for (let i = 0; i < entries.length; i++) {
      const entry = entries[i];
      const result = entry.listener(payload);
      results.push(result);
      if (entry.once) {
        toRemove[i] = true;
      }
    }

    if (toRemove.some(Boolean)) {
      const remaining = entries.filter((_, index) => !toRemove[index]);
      if (remaining.length === entries.length) {
        // No changes
      } else if (remaining.length === 0) {
        listeners.delete(event);
      } else {
        listeners.set(event, remaining);
      }
    }

    return results;
  }

  function listenerCount(event: string): number {
    const entries = listeners.get(event);
    return entries ? entries.length : 0;
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount
  };
}
