export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const state = new Map<string, { windowStart: number; count: number }>();

  function allow(key: string, nowMs: number): boolean {
    const oldState = state.get(key);
    let windowStart = oldState ? oldState.windowStart : nowMs;
    let count = oldState ? oldState.count : 0;

    if (nowMs - windowStart >= windowMs) {
      windowStart = nowMs;
      count = 0;
    }

    if (count < limit) {
      count++;
      state.set(key, { windowStart, count });
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const oldState = state.get(key);
    if (!oldState) {
      return limit;
    }

    if (nowMs - oldState.windowStart >= windowMs) {
      return limit;
    }

    return Math.max(0, limit - oldState.count);
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, remaining, reset };
}
