type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Listener[]>();
  const onceListeners = new Map<string, Listener[]>();

  return {
    on(event, listener) {
      const eventListeners = listeners.get(event) || [];
      eventListeners.push(listener);
      listeners.set(event, eventListeners);
      return eventListeners.length;
    },

    once(event, listener) {
      const eventOnceListeners = onceListeners.get(event) || [];
      eventOnceListeners.push(listener);
      onceListeners.set(event, eventOnceListeners);
      return eventOnceListeners.length;
    },

    off(event, listener) {
      const eventListeners = listeners.get(event);
      if (eventListeners) {
        const index = eventListeners.indexOf(listener);
        if (index !== -1) {
          eventListeners.splice(index, 1);
          return true;
        }
      }

      const eventOnceListeners = onceListeners.get(event);
      if (eventOnceListeners) {
        const index = eventOnceListeners.indexOf(listener);
        if (index !== -1) {
          eventOnceListeners.splice(index, 1);
          return true;
        }
      }

      return false;
    },

    emit(event, payload) {
      const results: unknown[] = [];
      const eventListeners = listeners.get(event) || [];
      const eventOnceListeners = onceListeners.get(event) || [];

      for (const listener of eventListeners) {
        results.push(listener(payload));
      }

      for (const listener of eventOnceListeners) {
        results.push(listener(payload));
      }

      onceListeners.delete(event);

      return results;
    },

    listenerCount(event) {
      const count = (listeners.get(event) || []).length + (onceListeners.get(event) || []).length;
      return count;
    },
  };
}
