      listeners.push(listener)
      listenersMap.set(event, listeners)
      return listeners.length
    },

    once(event: string, listener: Listener): number {
      const onceListener: Listener = (payload: unknown) => {
        (this as EventEmitter).off(event, onceListener)
        return listener(payload)
      }
      return this.on(event, onceListener)
    },

    off(event: string, listener: Listener): boolean {
      const listeners = listenersMap.get(event)
      if (!listeners) return false
      const index = listeners.indexOf(listener)
      if (index === -1) return false
      listeners.splice(index, 1)
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      const listeners = listenersMap.get(event) || []
      const results: unknown[] = []
      for (const l of listeners) {
        results.push(l(payload))
      }
      return results
    },

    listenerCount(event: string): number {
      return (listenersMap.get(event) || []).length
    }
  }
