type KeyState = {
  windowStart: number;
  requestCount: number;
};

const REQUESTS_PER_WINDOW = 3;
const WINDOW_MS = 1000;

export function createRateLimiter() {
  const state = new Map<string, KeyState>();

  function allow(key: string, nowMs: number): boolean {
    const existing = state.get(key);

    if (!existing || nowMs >= existing.windowStart + WINDOW_MS) {
      state.set(key, {
        windowStart: nowMs,
        requestCount: 0,
      });
    }

    const current = state.get(key)!;

    if (current.requestCount < REQUESTS_PER_WINDOW) {
      current.requestCount++;
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const existing = state.get(key);

    if (!existing || nowMs >= existing.windowStart + WINDOW_MS) {
      return REQUESTS_PER_WINDOW;
    }

    const current = existing;
    const remainder = REQUESTS_PER_WINDOW - current.requestCount;

    return remainder < 0 ? 0 : remainder;
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, remaining, reset };
}
