  subtract(n: number): Calculator
  multiply(n: number): Calculator
  divide(n: number): Calculator
  clear(): Calculator
  result(): number
  memoryStore(): Calculator
  memoryRecall(): number
  memoryClear(): Calculator
  memoryAdd(): Calculator
}

class Calculator {
  private result: number = 0;
  private memory: number = 0;

  constructor() {}

  public add(n: number): Calculator {
    this.result += n;
    return this;
  }

  public subtract(n: number): Calculator {
    this.result -= n;
    return this;
  }

  public multiply(n: number): Calculator {
    this.result *= n;
    return this;
  }

  public divide(n: number): Calculator {
    if (n === 0) {
      this.result = 0;
    } else {
      this.result /= n;
    }
    return this;
  }

  public clear(): Calculator {
    this.result = 0;
    return this;
  }

  public result(): number {
    return this.result;
  }

  public memoryStore(): Calculator {
    this.memory += this.result;
    return this;
  }

  public memoryRecall(): number {
    return this.memory;
  }

  public memoryClear(): Calculator {
    this.memory = 0;
    return this;
  }

  public memoryAdd(): Calculator {
    this.memory += this.result;
    return this;
  }
}

export function createCalculator(): Calculator {
  return new Calculator();
}
