type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Function[]>()

  return {
    on: (event, listener) => {
      if (!listeners.has(event)) {
        listeners.set(event, new Function[])
      }
      const listenersArray = listeners.get(event)
      listenersArray.push(listener)
      return listenersArray.length
    },
    once: (event, listener) => {
      if (!listeners.has(event)) {
        listeners.set(event, new Function[])
      }
      const listenersArray = listeners.get(event)
      listenersArray.push(listener)
      return listenersArray.length
    },
    off: (event, listener) => {
      if (listeners.has(event)) {
        const listenersArray = listeners.get(event)
        const index = listenersArray.indexOf(listener)
        if (index !== -1) {
          listenersArray.splice(index, 1)
          return true
        }
      }
      return false
    },
    emit: (event, payload) => {
      if (listeners.has(event)) {
        const listenersArray = listeners.get(event)
        const results = []
        for (const listener of listenersArray) {
          results.push(listener?.apply?.(this, [payload]))
        }
        return results
      }
      return []
    },
    listenerCount: (event) => {
      if (listeners.has(event)) {
        return listeners.get(event).length
      }
      return 0
    }
  }
}

