export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  return {
    allow: (key: string, nowMs: number): boolean => {
      if (windowStart.get(key) === undefined) {
        windowStart.set(key, nowMs);
        remaining.set(key, 0);
        return false;
      }

      if (nowMs - windowStart.get(key) >= windowMs) {
        windowStart.set(key, nowMs);
        remaining.set(key, 3);
        return true;
      }

      if (remaining.get(key) < limit) {
        remaining.set(key, remaining.get(key) + 1);
        return true;
      }

      return false;
    },
    remaining: (key: string, nowMs: number): number => {
      if (windowStart.get(key) === undefined) {
        return 0;
      }
      return remaining.get(key);
    },
    reset: (key: string) => {
      if (windowStart.get(key) !== undefined) {
        windowStart.set(key, nowMs);
      }
    }
  };
}

