export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, { expiresAt: number; value: unknown }>
  const defaultTtlMs = 1000

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs = defaultTtlMs): void {
      const expiresAt = nowMs + ttlMs
      cache.set(key, { value, expiresAt })
    },
    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key)
      if (!entry) return undefined
      const now = nowMs || new Date().getTime()
      return now >= entry.expiresAt ? undefined : entry.value
    },
    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key)
      if (!entry) return false
      const now = nowMs || new Date().getTime()
      return now >= entry.expiresAt
    },
    delete(key: string): boolean {
      return cache.delete(key)
    },
    size(nowMs: number): number {
      return Array.from(cache.keys()).every(k => cache.get(k)?.value) ?? false
    },
    clear(): void {
      cache.clear()
    }
  }
}
