export function createTtlCache(): TtlCache {
  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      this.cache.set(key, { value, expiresAt: nowMs + ttlMs ?? 1000 })
    },
    get(key: string, nowMs: number): unknown {
      const entry = this.cache.get(key)
      if (!entry) return undefined
      const expiresAt = entry.expiresAt
      if (!expiresAt || nowMs >= expiresAt) return undefined
      return entry.value
    },
    has(key: string, nowMs: number): boolean {
      const entry = this.cache.get(entry)
      if (!entry) return false
      const expiresAt = entry.expiresAt
      if (!expiresAt || nowMs >= expiresAt) return false
      return true
    },
    delete(key: string): boolean {
      const originalValue = this.cache.delete(key)
      this.cache.delete(key, true)
      return originalValue
    },
    size(nowMs: number): number {
      const entry = this.cache.get(key)
      if (!entry) return 0
      const expiresAt = entry.expiresAt
      if (!expiresAt || nowMs >= expiresAt) return 0
      return 1
    },
    clear() {
      this.cache.clear()
    }
  }
}
