export function createCalculator(): {
  add(n: number): this;
  subtract(n: number): this;
  multiply(n: number): this;
  divide(n: number): this;
  clear(): this;
  result(): number;
  memoryStore(): this;
  memoryAdd(): this;
  memoryClear(): this;
  memoryRecall(): number;
} {
  class Calculator {
    private current: number = 0;
    private memory: number = 0;

    add(n: number): this {
      this.current = this.current + n;
      return this;
    }

    subtract(n: number): this {
      this.current = this.current - n;
      return this;
    }

    multiply(n: number): this {
      this.current = this.current * n;
      return this;
    }

    divide(n: number): this {
      if (n === 0) {
        throw new Error('Cannot divide by zero');
      }
      this.current = this.current / n;
      return this;
    }

    clear(): this {
      this.current = 0;
      // memory is independent from current value
      return this;
    }

    result(): number {
      return this.current;
    }

    memoryStore(): this {
      this.memory = this.current;
      return this;
    }

    memoryAdd(): this {
      this.memory = this.memory + this.current;
      return this;
    }

    memoryClear(): this {
      this.memory = 0;
      return this;
    }

    memoryRecall(): number {
      return this.memory;
    }
  }

  return new Calculator();
}
