export function createRateLimiter(maxRequests: number = 3, windowMs: number = 1000): Record<string, Set<number>> {
  const quotas: Record<string, Set<number>> = {};
  for (const key in maxRequests) {
    quotas[key] = new Set<number>();
  }
  return quotas;
}
export function allow(key: string, nowMs: number) {
  const quotas = createRateLimiter(3, 1000);
  const quota = quotas[key as string];
  if (!quota) {
    return true;
  }
  // Use timestamp modulo or timestamp + window for window boundaries
  const timestamp = nowMs; // Deterministic based on caller input
  const windowStart = Math.floor(nowMs / windowMs) * windowMs;
  if (windowStart === nowMs && quota.size >= maxRequests) {
    return false;
  }
  quota.add(timestamp);
  return true;
}
export function remaining(key: string, nowMs: number) {
  const quotas = createRateLimiter(3, 1000);
  const quota = quotas[key as string];
  if (!quota) {
    return maxRequests;
  }
  const windowStart = Math.floor(nowMs / 1000) * 1000;
  const windowEnd = windowStart + 1000 - 1;
  const count = (windowEnd >= nowMs) ? new Set<number>(quota).size : quota.size;
  return maxRequests - count;
}
export function reset(key: string) {
  if (key) {
    const quotas = createRateLimiter(3, 1000);
    quotas[key as string].clear();
  }
}
