export function createEventEmitter() {
  interface ListenerWrapper {
    listener: (...args: any[]) => any;
    once: boolean;
  }

  const listeners = new Map<string, ListenerWrapper[]>();

  function on(event: string, listener: (...args: any[]) => any) {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const eventListeners = listeners.get(event)!;
    eventListeners.push({ listener, once: false });
    return eventListeners.length;
  }

  function once(event: string, listener: (...args: any[]) => any) {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const eventListeners = listeners.get(event)!;
    eventListeners.push({ listener, once: true });
    return eventListeners.length;
  }

  function off(event: string, listener: (...args: any[]) => any) {
    const eventListeners = listeners.get(event);
    if (!eventListeners) {
      return false;
    }
    const index = eventListeners.findIndex(item => item.listener === listener);
    if (index === -1) {
      return false;
    }
    eventListeners.splice(index, 1);
    return true;
  }

  function emit(event: string, payload: any) {
    const eventListeners = listeners.get(event);
    if (!eventListeners || eventListeners.length === 0) {
      return [];
    }

    const results: any[] = [];
    const indicesToRemove: number[] = [];

    for (let i = 0; i < eventListeners.length; i++) {
      const item = eventListeners[i];
      results.push(item.listener(payload));
      if (item.once) {
        indicesToRemove.push(i);
      }
    }

    // Remove once listeners in reverse order to preserve indices
    for (let i = indicesToRemove.length - 1; i >= 0; i--) {
      eventListeners.splice(indicesToRemove[i], 1);
    }

    return results;
  }

  function listenerCount(event: string) {
    const eventListeners = listeners.get(event);
    return eventListeners ? eventListeners.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}
