type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners: Map<string, Array<{ listener: Listener; once: boolean }>> = new Map();

  return {
    on(event: string, listener: Listener): number {
      let list = listeners.get(event);
      if (!list) {
        list = [];
        listeners.set(event, list);
      }
      list.push({ listener, once: false });
      return list.length;
    },
    once(event: string, listener: Listener): number {
      let list = listeners.get(event);
      if (!list) {
        list = [];
        listeners.set(event, list);
      }
      list.push({ listener, once: true });
      return list.length;
    },
    off(event: string, listener: Listener): boolean {
      const list = listeners.get(event);
      if (!list) return false;
      const index = list.findIndex(reg => reg.listener === listener);
      if (index === -1) return false;
      list.splice(index, 1);
      return true;
    },
    emit(event: string, payload: unknown): unknown[] {
      const list = listeners.get(event);
      if (!list || list.length === 0) return [];

      const snapshot = [...list];
      const results: unknown[] = [];
      const onceEntries: Array<{ listener: Listener; once: boolean }> = [];

      for (const reg of snapshot) {
        results.push(reg.listener(payload));
        if (reg.once) {
          onceEntries.push(reg);
        }
      }

      for (const reg of onceEntries) {
        const index = list.indexOf(reg);
        if (index !== -1) {
          list.splice(index, 1);
        }
      }

      return results;
    },
    listenerCount(event: string): number {
      const list = listeners.get(event);
      return list ? list.length : 0;
    },
  };
}

type RateLimiter = {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
};

export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;
  const state = new Map<string, { windowStart: number; count: number }>();

  function ensureKey(key: string, nowMs: number): { windowStart: number; count: number } {
    let entry = state.get(key);
    if (!entry || nowMs >= entry.windowStart + WINDOW_MS) {
      entry = { windowStart: nowMs, count: 0 };
      state.set(key, entry);
    }
    return entry;
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = ensureKey(key, nowMs);
      entry.count++;
      return entry.count <= LIMIT;
    },
    remaining(key: string, nowMs: number): number {
      const entry = ensureKey(key, nowMs);
      return Math.max(0, LIMIT - entry.count);
    },
    reset(key: string): void {
      state.delete(key);
    },
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const LIMIT = 3
  const WINDOW_MS = 1000
  const state = new Map<string, { count: number; windowStart: number }>()

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = state.get(key)
      if (!entry) {
        entry = { count: 0, windowStart: nowMs }
        state.set(key, entry)
      } else {
        if (nowMs - entry.windowStart >= WINDOW_MS) {
          entry.windowStart = nowMs
          entry.count = 0
        }
      }

      if (entry.count < LIMIT) {
        entry.count++
        return true
      }
      return false
    },
    remaining(key: string, nowMs: number): number {
      const entry = state.get(key)
      if (!entry) {
        return LIMIT
      }

      let effectiveCount = 0
      if (nowMs - entry.windowStart >= WINDOW_MS) {
        effectiveCount = 0
      } else {
        effectiveCount = entry.count
      }

      return LIMIT - effectiveCount
    },
    reset(key: string): void {
      state.delete(key)
    },
  }
}

