interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

interface KeyState {
  requestId: number;
  lastWindowStart: number;
}

interface RateLimiterFactory {
  (): RateLimiter;
}

const WINDOW_SIZE_MS = 1000;
const MAX_REQUESTS_PER_WINDOW = 3;

function getWindowStart(nowMs: number): number {
  return Math.floor(nowMs / WINDOW_SIZE_MS) * WINDOW_SIZE_MS;
}

const createRateLimiter: RateLimiterFactory = (): RateLimiter => {
  const keyState = new Map<string, KeyState>();

  return {
    allow(key: string, nowMs: number): boolean {
      const windowStart = getWindowStart(nowMs);

      const existing = keyState.get(key);
      if (existing) {
        if (existing.lastWindowStart !== windowStart) {
          keyState.set(key, { requestId: 0, lastWindowStart: windowStart });
        }
      } else {
        keyState.set(key, { requestId: 0, lastWindowStart: windowStart });
      }

      const state = keyState.get(key)!;
      if (state.requestId >= MAX_REQUESTS_PER_WINDOW) {
        return false;
      }
      state.requestId++;
      return true;
    },

    remaining(key: string, nowMs: number): number {
      const windowStart = getWindowStart(nowMs);

      const existing = keyState.get(key);
      let state: KeyState;

      if (existing) {
        if (existing.lastWindowStart === windowStart) {
          state = existing;
        } else {
          state = { requestId: 0, lastWindowStart: windowStart };
          keyState.set(key, state);
        }
      } else {
        state = { requestId: 0, lastWindowStart: windowStart };
        keyState.set(key, state);
      }

      return Math.max(0, MAX_REQUESTS_PER_WINDOW - state.requestId);
    },

    reset(key: string): void {
      keyState.delete(key);
    }
  };
};

export { createRateLimiter };
