function createEventEmitter() {
  const listeners = new Map<string, Array<{
    listener: (payload: any) => any;
    once: boolean;
  }>>();

  function on(event: string, listener: (payload: any) => any) {
    let array = listeners.get(event);
    if (!array) {
      array = [];
      listeners.set(event, array);
    }
    array.push({ listener, once: false });
    return array.length;
  }

  function once(event: string, listener: (payload: any) => any) {
    let array = listeners.get(event);
    if (!array) {
      array = [];
      listeners.set(event, array);
    }
    array.push({ listener, once: true });
    return array.length;
  }

  function off(event: string, listener: (payload: any) => any) {
    const array = listeners.get(event);
    if (!array) {
      return false;
    }
    const index = array.findIndex(item => item.listener === listener);
    if (index === -1) {
      return false;
    }
    array.splice(index, 1);
    return true;
  }

  function emit(event: string, payload: any) {
    const array = listeners.get(event);
    if (!array) {
      return [];
    }
    const results: any[] = [];
    for (let i = 0; i < array.length; i++) {
      const item = array[i];
      results.push(item.listener(payload));
      if (item.once) {
        array.splice(i, 1);
        i--;
      }
    }
    return results;
  }

  function listenerCount(event: string) {
    const array = listeners.get(event);
    return array ? array.length : 0;
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount
  };
}

export { createEventEmitter };
