export function createRateLimiter() {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;

  const state = new Map<string, { windowStart: number; requestCount: number }>();

  function allow(key: string, nowMs: number): boolean {
    const stored = state.get(key);
    const windowStart = stored && (nowMs - stored.windowStart) < WINDOW_MS
      ? stored.windowStart
      : nowMs;

    if (!stored || (nowMs - stored.windowStart) >= WINDOW_MS) {
      state.set(key, { windowStart, requestCount: 1 });
      return true;
    }

    if (stored.requestCount < MAX_REQUESTS) {
      stored.requestCount++;
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const stored = state.get(key);
    const windowStart = stored && (nowMs - stored.windowStart) < WINDOW_MS
      ? stored.windowStart
      : nowMs;

    const requestCount = stored && (nowMs - stored.windowStart) < WINDOW_MS
      ? stored.requestCount
      : 0;

    return Math.max(0, MAX_REQUESTS - requestCount);
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, remaining, reset };
}
