interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limits = new Map<string, { count: number; windowStart: number }>()
  const limit = 3
  const windowMs = 1000

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = limits.get(key)

      if (!entry || nowMs - entry.windowStart >= windowMs) {
        limits.set(key, { count: 0, windowStart: nowMs })
        return true
      }

      const state = limits.get(key)!

      if (state.count >= limit) {
        return false
      }

      state.count++
      return true
    },

    remaining(key: string, nowMs: number): number {
      const entry = limits.get(key)

      if (!entry || nowMs - entry.windowStart >= windowMs) {
        return limit
      }

      return Math.max(0, limit - entry.count)
    },

    reset(key: string): void {
      limits.delete(key)
    }
  }
}
