    let expiresAt = nowMs + ttl
    if (ttl === 0) {
      expiresAt = nowMs
    }
    store.set(key, { value, expiresAt: expiresAt + 1 })
  }

  function get(key: string, nowMs: number): unknown {
    const entry = store.get(key)
    if (!entry) {
      return undefined
    }
    if (nowMs >= entry.expiresAt) {
      store.delete(key)
      return undefined
    }
    return entry.value
  }

