export function createEventEmitter() {
  const listeners = new Map<string, { normal: Function[]; once: Function[] }>();

  const addListenersToEvent = (event: string, fn: Function) => {
    if (!listeners.has(event)) {
      listeners.set(event, { normal: [], once: [] });
    }
  };

  const on = (event: string, fn: Function): number => {
    addListenersToEvent(event, fn);
    const eventListeners = listeners.get(event)!;
    eventListeners.normal.push(fn);
    return listeners.size; // Note: Spec asks for "listener count for that event"
  };

  // Wait, "listener count for that event". This means count of listeners for 'event', not number of Map entries.
  const countForEvent = (event: string): number => {
    const eventListeners = listeners.get(event);
    if (!eventListeners) return 0;
    return eventListeners.normal.length + eventListeners.once.length;
  };

  const onImpl = (event: string, fn: Function): number => {
    const eventListeners = listeners.get(event);
    if (!eventListeners) {
      listeners.set(event, { normal: [], once: [] });
    }
    eventListeners.normal.push(fn);
    return eventListeners.normal.length + eventListeners.once.length;
  };

  const onceImpl = (event: string, fn: Function): number => {
    addListenersToEvent(event, fn);
    const eventListeners = listeners.get(event)!;
    eventListeners.once.push(fn);
    return eventListeners.normal.length + eventListeners.once.length;
  };

  const offImpl = (event: string, fn: Function): boolean => {
    const eventListeners = listeners.get(event);
    if (!eventListeners) return false;

    let removed = false;
    const index = eventListeners.normal.findIndex(l => l === fn);
    if (index !== -1) {
      eventListeners.normal.splice(index, 1);
      removed = true;
    } else {
      const indexOnce = eventListeners.once.findIndex(l => l === fn);
      if (indexOnce !== -1) {
        eventListeners.once.splice(indexOnce, 1);
        removed = true;
      }
    }
    return removed;
  };

  const emitImpl = (event: string, payload: any): any[] => {
    const eventListeners = listeners.get(event);
    if (!eventListeners) return [];

    const listeners = [...eventListeners.normal, ...eventListeners.once];
    const results = [];

    // We need to remove once listeners after they fire.
    // To support the removal correctly without breaking the iteration of `normal` listeners,
    // we can iterate normally, but for `once` listeners we record their indices in `once` array to remove.

    // However, `once` listeners are separate from `normal`.
    // Let's iterate normal then once.
    // For `once`, we execute and then remove it.
    // To remove correctly, we should probably collect them and remove them after?
    // Or just remove immediately to ensure they are not called again?
    // The standard behavior for `once` is to fire once and then be removed from the list so it doesn't fire again on subsequent `emit` calls.

    // Implementation: 
    // 1. Run normal listeners.
    // 2. Run once listeners (and remove them from the list).
    // 3. But wait, if we run normal listeners, they don't get removed.
    // 4. `emit` returns values.

    // Wait, if `emit` runs multiple listeners, we should remove `once` listeners immediately after they fire?
    // Or after `emit`?
    // If we remove immediately, it's hard to guarantee order of execution vs removal.
    // Actually, `once` listeners are registered *once*.
    // We should remove them from the list *after* `emit`?
    // If we remove after `emit`, they might be called again.
    // So we must remove them.
    // If we remove them after they fire, we must ensure they fire only once per `emit`.
    // But `once` listeners fire in the `emit` cycle.
    // If I run `once` listener, it fires, and I remove it.
    // This ensures it fires once per `emit`.
    // So I will iterate, execute, and if it's `once`, remove it from `once` array.
    // Wait, removing while iterating the array is tricky.
    // Better to store the listeners in a single array `events` and store type.
    // `Map<string, Array<{ type: 'once' | 'normal', fn: Function }>>`
    // Then `emit` iterates the array.
    // If `type === 'once'`, execute `fn`, remove from array *after execution*?
    // If I have multiple `once` listeners.
    // I need to remove *after* execution to avoid modifying while iterating.
    // `const list = [...listeners[event].map(l => l.fn), ...listeners[event].once.map(l => l.fn)]`
    // Wait, `emit` iterates `normal` then `once`.
    // If I remove from `once` array, I need to identify which one is which.

    // Let's use a cleaner approach.
    // `emit` runs all listeners.
    // `once` listeners are removed after execution.
    // To do this, I can iterate through all listeners (Normal then Once), execute them, and add a flag to track which were `once`.
    // Then `splice` them from `once` array.
    // Actually, `once` array is separate from `normal`.
    // I'll iterate `normal`, then `once`.
    // For `once`, I can mark it as "fired".
    // Then after the loop, remove from `once`.
    // But wait, if I mark it as "fired", I need to ensure it's removed from the map.
    // Let's store `{ fn, isOnce, fired }`?
    // Actually, if I just store the listeners in the Map, and for `once`, I add a separate `removed` flag to the object or array.
    // Or I can just `splice` from `once` immediately after execution?
    // No, because `once` listeners might be registered multiple times?
    // `once` is a specific type.

    // Simpler: `once` listeners are removed from the `once` array *immediately after* `emit` fires them.
    // So `emit` iterates `once` array. For each, `fn(payload)`. Then `splice` the *fired* one from `once` array.
    // How to know which ones fired? All of them.
    // So `emit` runs them, then removes them.
    // Wait, if I run `once` listener, execute it, then remove it.
    // If I remove it, I should remove it from `once` array.
    // I'll just remove *all* `once` listeners from the `once` array at the end of `emit`?
    // Yes, because they were all fired in this `emit` call.
    // This is consistent with `once` behavior (fire once, remove).
    // I'll execute `once` listeners, collect results.
    // Then after collecting results, remove all `once` listeners from `once` array.
    // Wait, `once` listeners are removed after `emit`.
    // So `listenerCount` should reflect that they are gone?
    // `listenerCount` returns current listener count.
    // If they are removed, count is lower.
    // If I remove them *after* `emit` returns, they are counted as 0?
    // Yes.
    // So `listenerCount` after `emit` returns 0 for `once` listeners.
    // `on` returns count *before* removal?
    // `on` returns count for that event.
    // I will return the count of listeners in the event.

    // Wait, the `on` and `once` return "listener count for that event".
    // Does it mean `listenerCount(event)`?
    // Yes.
    // I will calculate count.

    // Let's write the code.

    const results = [];
    // Run Normal listeners
    eventListeners.normal.forEach(fn => {
      results.push(fn(payload));
    });
    // Run Once listeners
    const onceToRun = [...eventListeners.once];
    const count = onceToRun.length;
    eventListeners.once.forEach(fn => {
      results.push(fn(payload));
    });
    // Remove Once listeners
    if (count > 0) {
      // Remove all once listeners
      // But I should remove them from the map
      // `splice` from once list
      // If I remove them, `listenerCount` should reflect.
      // I'll do `splice` here.
      // Wait, `once` listeners are in `eventListeners.once`.
      // I need to remove them.
      // But `onceToRun` is a copy.
      // So I'll remove `eventListeners.once`?
      // No, `eventListeners.once` is the source of truth.
      // I'll just remove `eventListeners.once` if count > 0?
      // Yes.
      // Wait, if I have duplicate `once` listeners (e.g. registered twice with `once`).
      // Should they be removed?
      // Yes, they are `once`. They fired. They are gone.
      // So `eventListeners.once.splice(0, count)`?
      // Or `splice` the specific indices?
      // All of them.
      eventListeners.once.splice(0, count);
    }

    return results;
  };

  const listenerCountImpl = (event: string): number => {
    return countForEvent(event);
  };

  return {
    on: onImpl,
    once: onceImpl,
    off: offImpl,
    emit: emitImpl,
    listenerCount: listenerCountImpl
  };
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export class EventEmitter {
  private listeners: Map<string, Array<{ fn: Listener, isOnce: boolean }>>

  constructor() {
    this.listeners = new Map()
  }

  on(event: string, listener: Listener): number {
    const count = this.listeners.get(event)?.length || 0
    const list = this.listeners.get(event) || []
    list.push({ fn: listener, isOnce: false })
    this.listeners.set(event, list)
    return count + 1
  }

  once(event: string, listener: Listener): number {
    const count = this.listeners.get(event)?.length || 0
    const list = this.listeners.get(event) || []
    list.push({ fn: listener, isOnce: true })
    this.listeners.set(event, list)
    return count + 1
  }

  off(event: string, listener: Listener): boolean {
    const list = this.listeners.get(event)
    if (!list) return false
    for (let i = 0; i < list.length; i++) {
      if (list[i].fn === listener) {
        list.splice(i, 1)
        this.listeners.set(event, list)
        return true
      }
    }
    return false
  }

  emit(event: string, payload: unknown): unknown[] {
    const list = this.listeners.get(event)
    if (!list) return []
    const results: unknown[] = []
    for (const h of list) {
      results.push(h.fn(payload))
    }
    // Remove once listeners after invocation
    for (let i = list.length - 1; i >= 0; i--) {
      if (list[i].isOnce) {
        list.splice(i, 1)
      }
    }
    this.listeners.set(event, list)
    return results
  }

  listenerCount(event: string): number {
    return this.listeners.get(event)?.length || 0
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitter()
}

export function createRateLimiter(): {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
} {
    const state = new Map<string, { lastWindowStart: number; count: number }>();
    const WINDOW_MS = 1000;
    const MAX_REQUESTS = 3;

    function getEntry(key: string) {
        return state.get(key);
    }

    function setEntry(key: string, value: { lastWindowStart: number; count: number }) {
        state.set(key, value);
    }

    return {
        allow: (key: string, nowMs: number): boolean => {
            const entry = getEntry(key);
            if (!entry) {
                setEntry(key, { lastWindowStart: nowMs, count: 0 });
                return true;
            }
            const isExpired = nowMs - entry.lastWindowStart >= WINDOW_MS;
            if (isExpired) {
                setEntry(key, { lastWindowStart: nowMs, count: 0 });
                return true;
            }
            if (entry.count >= MAX_REQUESTS) {
                return false;
            }
            setEntry(key, { lastWindowStart: entry.lastWindowStart, count: entry.count + 1 });
            return true;
        },
        remaining: (key: string, nowMs: number): number => {
            const entry = getEntry(key);
            if (!entry) {
                return MAX_REQUESTS;
            }
            const isExpired = nowMs - entry.lastWindowStart >= WINDOW_MS;
            if (isExpired) {
                return MAX_REQUESTS;
            }
            return Math.max(0, MAX_REQUESTS - entry.count);
        },
        reset: (key: string) => {
            state.delete(key);
        }
    };
}

const LIMIT = 3;
const WINDOW_MS = 1000;

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

function createRateLimiter(): RateLimiter {
  const stateMap = new Map<string, { count: number; windowStart: number }>();

  return {
    allow: (key: string, nowMs: number): boolean => {
      let state = stateMap.get(key);
      if (!state) {
        state = { count: 0, windowStart: nowMs };
        stateMap.set(key, state);
      } else {
        if (nowMs - state.windowStart >= WINDOW_MS) {
          state.count = 0;
          state.windowStart = nowMs;
          stateMap.set(key, state);
        }
      }

      if (state.count < LIMIT) {
        state.count++;
        stateMap.set(key, state);
        return true;
      }
      return false;
    },
    remaining: (key: string, nowMs: number): number => {
      let state = stateMap.get(key);
      if (!state) {
        state = { count: 0, windowStart: nowMs };
        stateMap.set(key, state);
      } else {
        if (nowMs - state.windowStart >= WINDOW_MS) {
          state.count = 0;
          state.windowStart = nowMs;
          stateMap.set(key, state);
        }
      }

      return LIMIT - state.count;
    },
    reset: (key: string): void => {
      stateMap.delete(key);
    }
  };
}

