type Entry = { value: unknown; expiresAt: number };

interface CacheAPI {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

function createTtlCache(): CacheAPI {
  const map = new Map<string, Entry>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number | undefined) {
      const expiresAt = nowMs + (ttlMs ?? 1000);
      map.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = map.get(key);
      if (!entry) {
        return undefined;
      }
      if (nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = map.get(key);
      return entry !== undefined && nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      return map.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const entry of map.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear() {
      map.clear();
    },
  };
}

export function createTtlCache(): CacheAPI {
  return createTtlCache();
