type Listener = (payload: unknown) => unknown

interface EventEmitter {
    on(event: string, listener: Listener): number
    once(event: string, listener: Listener): number
    off(event: string, listener: Listener): boolean
    emit(event: string, payload: unknown): unknown[]
    listenerCount(event: string): number
}

function createEventEmitter(): EventEmitter {
    const listeners: Map<string, Array<Listener>> = new Map()

    function on(event: string, listener: Listener): number {
        if (!listeners.has(event)) {
            listeners.set(event, [])
        }
        const count = listeners.get(event)!.length
        listeners.get(event)![count].push(listener)
        return count + 1
    }

    function once(event: string, listener: Listener): number {
        const wrappedListener = (...args: unknown[]) => {
            listener(...args)
            const index = listeners.get(event)?.indexOf(wrappedListener)
            if (index !== -1) {
                listeners.get(event)!.splice(index, 1)
            }
        }
        on(event, wrappedListener)
    }

    function off(event: string, listener: Listener): boolean {
        const eventListeners = listeners.get(event)
        if (!eventListeners) return false

        const index = eventListeners.indexOf(listener)
        if (index === -1) return false

        eventListeners.splice(index, 1)
        return true
    }

    function emit(event: string, payload: unknown): unknown[] {
        const eventListeners = listeners.get(event) || []
        const results: unknown[] = []

        for (const listener of eventListeners) {
            results.push(listener(payload))
        }

        return results
    }

    function listenerCount(event: string): number {
        const eventListeners = listeners.get(event)
        return eventListeners ? eventListeners.length : 0
    }

    return {
        on,
        once,
        off,
        emit,
        listenerCount
    }
}

export { createEventEmitter }
