  memoryStore(): Calculator {
    this.memory = this.current;
    return this;
  }

  memoryRecall(): number {
    return this.memory;
  }

  memoryAdd(): Calculator {
    this.memory = this.memory + this.current;
    return this;
  }

  memoryClear(): Calculator {
    this.memory = 0;
    return this;
  }
}

