const createEventEmitter = (name: string | symbol): EventEmitter => {
  interface Listener {
    (this: any, event: string | symbol, payload: any): any;
  }

  type Events = Record<keyof typeof EventEmitter, Listener[]>;
  const events: Map<any, Listener[]> = new Map();
  const oneTimeListeners = new Map<any, Listener[]>();

  const on = (event: any, listener: Listener): number => {
    const list = events.get(event) || [];
    events.set(event, [...list, listener]);
    // Track one-time listeners
    const onceList = oneTimeListeners.get(event) || [];
    oneTimeListeners.set(event, [...onceList, listener]);
    return list.length;
  };

  const once = (event: any, listener: Listener): number => {
    const list = events.get(event) || [];
    events.set(event, [...list, listener]);
    const onceList = oneTimeListeners.get(event) || [];
    oneTimeListeners.set(event, [...onceList, listener]);
    return list.length;
  };

  const off = (event: any, listener: Listener): boolean => {
    const listeners = events.get(event);
    if (!listeners) return false;

    const beforeIndex = listeners.indexOf(listener);
    if (beforeIndex === -1) return false;

    // Remove only the first matching listener
    listeners.splice(beforeIndex, 1);
    return true;
  };

  const emit = (event: any, payload: any): any[] => {
    const listeners = events.get(event);
    if (!listeners) return [];

    const oneTimeList = oneTimeListeners.get(event);
    // We need to emit normal listeners first, then one-time listeners
    // and track which one-time listeners have been called
    const oneTimeCount = oneTimeList ? oneTimeList.length : 0;
    const result: any[] = [];

    // First emit normal listeners in order
    listeners.forEach((l: Listener) => {
      try {
        result.push(l.apply(null, [payload]));
      } catch (e) {
        result.push(e);
      }
    });

    // Then emit one-time listeners (only once each)
    const emitted: Set<any> = new Set();
    (oneTimeList || []).forEach((l: Listener) => {
      if (emitted.has(l)) return;
      emitted.add(l);
      try {
        result.push(l.apply(null, [payload]));
      } catch (e) {
        result.push(e);
      }
    });

    return result;
  };

  const listenerCount = (event: any): number => {
    return events.get(event)?.length || 0;
  };

  return { on, once, off, emit, listenerCount };
};

export { createEventEmitter };
