export const createRateLimiter = (): {
	allow(key: string, nowMs: number): boolean;
	remaining(key: string, nowMs: number): number;
	reset(key: string): void;
} => {
	const limits: Record<string, {
		total: number;
		lastReset: number;
		lastRequest: number;
	}> = {};

	const returnAllow = (key: string, nowMs: number): boolean => {
		const limit = limits[key];
		const windowSize = 1000;
		const quota = 3;

		if (!limit) {
			limits[key] = { total: quota, lastReset: nowMs, lastRequest: nowMs };
			return true;
		}

		const nowInWindow = nowMs - limit.lastReset;
		const nextRequest = (limit.lastRequest || nowMs) + windowSize;

		if (nowInWindow === 0 || nowInWindow >= 1000) {
			limits[key] = { total: quota, lastReset: nowMs, lastRequest: nowMs };
			return true;
		}

		if (limit.total === 0) {
			return false;
		}

		limit.total -= 1;
		limit.lastRequest = nowMs;
		return true;
	};

	const returnRemaining = (key: string, nowMs: number): number => {
		const limit = limits[key];
		const windowSize = 1000;
		const quota = 3;

		if (!limit || nowMs >= limit.lastReset + windowSize) {
			limits[key] = { total: quota, lastReset: nowMs, lastRequest: nowMs };
			return quota;
		}

		return limit.total >= 0 ? limit.total : 0;
	};

	return {
		allow: returnAllow,
		remaining: returnRemaining,
		reset: (key: string) => {
			if (limits[key]) {
				delete limits[key];
			}
		},
	};
};
