  function getOrInitState(key: string): KeyState {
    if (!keyStates.has(key)) {
      keyStates.set(key, { windowStart: 0, remaining: limit })
    }
    return keyStates.get(key)!
  }

  function getRemaining(key: string, nowMs: number): number {
    const state = getOrInitState(key)
    if (nowMs - state.windowStart >= windowMs) {
      state.windowStart = nowMs
      state.remaining = limit
    }
    return state.remaining
  }

  function resetState(key: string): void {
    keyStates.delete(key)
  }

  return {
    allow: function(key: string, nowMs: number): boolean {
      const remaining = getRemaining(key, nowMs)
      if (remaining <= 0) {
        return false
      }
      const state = getOrInitState(key)
      state.remaining--
      return true
    },
    remaining: function(key: string, nowMs: number): number {
      return getRemaining(key, nowMs)
    },
    reset: function(key: string): void {
      resetState(key)
    }
  }
}
