const DEFAULT_TTL_MS = 1000

interface CacheEntry {
  value: unknown
  expiresAt: number
}

const createTtlCache = (): TtlCache => {
  const cache: Map<string, CacheEntry> = new Map()

  const getExpiresAt = (nowMs: number, ttlMs?: number): number => {
    const effectiveTtl = ttlMs ?? DEFAULT_TTL_MS
    return nowMs + effectiveTtl
  }

  const isExpired = (expiresAt: number, nowMs: number): boolean => nowMs >= expiresAt

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    const expiresAt = getExpiresAt(nowMs, ttlMs)
    cache.set(key, { value, expiresAt })
  }

  const get = (key: string, nowMs: number): unknown => {
    const entry = cache.get(key)
    if (!entry) return undefined
    if (isExpired(entry.expiresAt, nowMs)) return undefined
    return entry.value
  }

  const has = (key: string, nowMs: number): boolean => {
    const entry = cache.get(key)
    if (!entry) return false
    return !isExpired(entry.expiresAt, nowMs)
  }

  const delete_ = (key: string): boolean => {
    return cache.delete(key)
  }

  const size = (nowMs: number): number => {
    let count = 0
    for (const entry of cache.values()) {
      if (!isExpired(entry.expiresAt, nowMs)) {
        count++
      }
    }
    return count
  }

  const clear = (): void => {
    cache.clear()
  }

  return {
    set,
    get,
    has,
    delete_,
    size,
    clear
  }
}

