interface Calculator {
  add(n: number): Calculator;
  subtract(n: number): Calculator;
  multiply(n: number): Calculator;
  divide(n: number): Calculator;
  clear(): Calculator;
  result(): number;
  memoryStore(): Calculator;
  memoryRecall(): number;
  memoryClear(): Calculator;
  memoryAdd(): Calculator;
}

export function createCalculator(): Calculator {
  const self = {
    current: 0,
    memory: 0,
    add: (n: number): Calculator => {
      self.current += n;
      return self;
    },
    subtract: (n: number): Calculator => {
      self.current -= n;
      return self;
    },
    multiply: (n: number): Calculator => {
      self.current *= n;
      return self;
    },
    divide: (n: number): Calculator => {
      if (n === 0) {
        self.current = Infinity; // or NaN, typically JS throws/isNaN
        // Standard JS behavior for division by zero is Infinity
        return self;
      }
      self.current /= n;
      return self;
    },
    clear: (): Calculator => {
      self.current = 0;
      return self;
    },
    result: (): number => {
      return self.current;
    },
    memoryStore: (): Calculator => {
      self.memory = self.current;
      return self;
    },
    memoryRecall: (): number => {
      return self.memory;
    },
    memoryClear: (): Calculator => {
      self.memory = 0;
      return self;
    },
    memoryAdd: (): Calculator => {
      self.memory += self.current;
      return self;
    },
  };
  return self as Calculator;
}

export function createEventEmitter() {
  const listenersMap = new Map<string, { fn: (...args: any[]) => any; once: boolean }[]>();

  function on(event: string, listener: (...args: any[]) => any): number {
    if (!listenersMap.has(event)) {
      listenersMap.set(event, []);
    }
    const list = listenersMap.get(event)!;
    list.push({ fn: listener, once: false });
    return list.length;
  }

  function once(event: string, listener: (...args: any[]) => any): number {
    if (!listenersMap.has(event)) {
      listenersMap.set(event, []);
    }
    const list = listenersMap.get(event)!;
    list.push({ fn: listener, once: true });
    return list.length;
  }

  function off(event: string, listener: (...args: any[]) => any): boolean {
    if (!listenersMap.has(event)) {
      return false;
    }
    const list = listenersMap.get(event)!;
    const index = list.findIndex(item => item.fn === listener);
    if (index !== -1) {
      list.splice(index, 1);
      return true;
    }
    return false;
  }

  function listenerCount(event: string): number {
    const list = listenersMap.get(event);
    return list ? list.length : 0;
  }

  function emit(event: string, payload: any): any[] {
    const list = listenersMap.get(event);
    if (!list) return [];

    const results: any[] = [];
    const onceIndices: number[] = [];

    for (let i = 0; i < list.length; i++) {
      const { fn } = list[i];
      const result = fn(payload);
      results.push(result);
      if (list[i].once) {
        onceIndices.push(i);
      }
    }

    // Remove once listeners to prevent re-firing in subsequent emits
    // Sort descending to splice safely
    onceIndices.sort((a, b) => b - a);
    onceIndices.forEach(idx => list.splice(idx, 1));

    return results;
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ listener: Listener; isOnce: boolean }>>()

  return {
    on(event, listener) {
      const list = listeners.get(event) || []
      list.push({ listener, isOnce: false })
      listeners.set(event, list)
      return list.length
    },
    once(event, listener) {
      const list = listeners.get(event) || []
      list.push({ listener, isOnce: true })
      listeners.set(event, list)
      return list.length
    },
    off(event, listener) {
      const list = listeners.get(event)
      if (!list) {
        return false
      }
      const index = list.findIndex(l => l.listener === listener)
      if (index !== -1) {
        list.splice(index, 1)
        return true
      }
      return false
    },
    emit(event, payload) {
      const list = listeners.get(event)
      if (!list) {
        return []
      }
      const results: unknown[] = []
      let index = 0
      while (index < list.length) {
        const l = list[index]
        results.push(l.listener(payload))
        if (l.isOnce) {
          list.splice(index, 1)
          // Do not increment index, next listener is now at current index
        } else {
          index++
        }
      }
      return results
    },
    listenerCount(event) {
      const list = listeners.get(event)
      return list ? list.length : 0
    },
  }
}

export function createRateLimiter() {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;
  const store = new Map<string, { count: number; windowStart: number }>();

  return {
    allow: (key: string, nowMs: number) => {
      let state = store.get(key);
      if (!state) {
        state = { count: 0, windowStart: nowMs };
        store.set(key, state);
      }

      if (nowMs - state.windowStart >= WINDOW_MS) {
        state.windowStart = nowMs;
        state.count = 0;
      }

      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }
      return false;
    },
    remaining: (key: string, nowMs: number) => {
      let state = store.get(key);
      if (!state) {
        state = { count: 0, windowStart: nowMs };
        store.set(key, state);
      }

      if (nowMs - state.windowStart >= WINDOW_MS) {
        state.windowStart = nowMs;
        state.count = 0;
      }

      return Math.max(0, MAX_REQUESTS - state.count);
    },
    reset: (key: string) => {
      store.delete(key);
    }
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

const LIMIT = 3;
const WINDOW_MS = 1000;

export function createRateLimiter(): RateLimiter {
  const stateMap = new Map<string, { count: number; windowStart: number }>();

  return {
    allow: (key: string, nowMs: number): boolean => {
      let existing = stateMap.get(key);

      if (!existing) {
        existing = { count: 0, windowStart: nowMs };
        stateMap.set(key, existing);
      } else {
        const diff = nowMs - existing.windowStart;
        if (diff >= WINDOW_MS) {
          existing.count = 0;
          existing.windowStart = nowMs;
        }
      }

      if (existing.count < LIMIT) {
        existing.count++;
        return true;
      }
      return false;
    },
    remaining: (key: string, nowMs: number): number => {
      const existing = stateMap.get(key);
      if (!existing) {
        return LIMIT;
      }
      const diff = nowMs - existing.windowStart;
      if (diff >= WINDOW_MS) {
        return LIMIT;
      }
      return Math.max(0, LIMIT - existing.count);
    },
    reset: (key: string): void => {
      stateMap.delete(key);
    }
  };
}

