interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();
  const defaultTtl = 1000;

  const getEntry = (key: string) => cache.get(key);

  return {
    set(key, value, nowMs, ttlMs) {
      const ttl = ttlMs ?? defaultTtl;
      const expiresAt = nowMs + ttl;
      cache.set(key, { value, expiresAt });
    },
    get(key, nowMs) {
      const entry = getEntry(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        cache.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key, nowMs) {
      const entry = getEntry(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        cache.delete(key);
        return false;
      }
      return true;
    },
    delete(key) {
      return cache.delete(key);
    },
    size(nowMs) {
      let count = 0;
      const iterator = cache.entries();
      for (const [key, entry] of iterator) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
          cache.delete(key);
        }
      }
      return count;
    },
    clear() {
      cache.clear();
    },
  };
}
