interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

const limiterState = new Map<string, {
  windowStart: number;
  count: number;
}>();

export function createRateLimiter(): RateLimiter {
  const limiter = {
    allow: function(key: string, nowMs: number): boolean {
      const windowMs = 1000;
      const limit = 3;
      const windowStart = windowMs * Math.floor(nowMs / windowMs);

      let keyState = limiterState.get(key);

      if (keyState === undefined) {
        limiterState.set(key, {
          windowStart: windowStart,
          count: 0
        });
        keyState = limiterState.get(key)!;
      }

      if (nowMs >= keyState.windowStart + windowMs) {
        keyState.windowStart = windowStart;
        keyState.count = 0;
      }

      if (keyState.count < limit) {
        keyState.count++;
        return true;
      } else {
        return false;
      }
    },

    remaining: function(key: string, nowMs: number): number {
      const windowMs = 1000;
      const limit = 3;
      const windowStart = windowMs * Math.floor(nowMs / windowMs);

      let keyState = limiterState.get(key);

      if (keyState === undefined) {
        limiterState.set(key, {
          windowStart: windowStart,
          count: 0
        });
        keyState = limiterState.get(key)!;
      }

      if (nowMs >= keyState.windowStart + windowMs) {
        keyState.windowStart = windowStart;
        keyState.count = 0;
      }

      return Math.max(0, limit - keyState.count);
    },

    reset: function(key: string): void {
      limiterState.delete(key);
    }
  };

  return limiter;
}
