export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, [{
    callback: Listener;
    type: "once" | "on"
  }[]]>()

  interface EventEmitter {
    on(event: string, listener: Listener): number
    once(event: string, listener: Listener): number
    off(event: string, listener: Listener): boolean
    emit(event: string, payload: unknown): unknown[]
    listenerCount(event: string): number
  }

  function on(event: string, listener: Listener): number {
    let arr = listeners.get(event)
    if (arr == null) {
      arr = []
      listeners.set(event, arr)
    }
    arr.push({ callback: listener, type: "on" })
    return arr.length
  }

  function once(event: string, listener: Listener): number {
    let arr = listeners.get(event)
    if (arr == null) {
      arr = []
      listeners.set(event, arr)
    }
    arr.push({ callback: listener, type: "once" })
    return arr.length
  }

  function off(event: string, listener: Listener): boolean {
    const arr = listeners.get(event)
    if (arr == null) return false
    const idx = arr.findIndex(l => l.callback === listener)
    if (idx !== -1) {
      arr.splice(idx, 1)
      return true
    }
    return false
  }

  function emit(event: string, payload: unknown): unknown[] {
    const arr = listeners.get(event)
    if (arr == null) return []
    const results: unknown[] = []
    for (let i = 0; i < arr.length; i++) {
      const { callback, type } = arr[i]
      results.push(callback(payload))
      if (type === "once") {
        arr.splice(i, 1)
      }
    }
    return results
  }

  function listenerCount(event: string): number {
    const arr = listeners.get(event)
    return arr ? arr.length : 0
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount
  }
}

export type Listener = (payload: unknown) => unknown
export interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}
