export function createRateLimiter(): {
  allow: (key: string, nowMs: number) => boolean
  remaining: (key: string, nowMs: number) => number
  reset: (key: string) => void
} {
  const stores = new Map<string, { count: number; windowStart: number }>()

  const MAX_REQUESTS = 3
  const WINDOW_MS = 1000

  function getStore(key: string, nowMs: number) {
    const store = stores.get(key)

    if (!store) {
      return { count: 0, windowStart: nowMs }
    }

    if (nowMs - store.windowStart >= WINDOW_MS) {
      return { count: 0, windowStart: nowMs }
    }

    return store
  }

  function recordRequest(key: string, nowMs: number) {
    const store = getStore(key, nowMs)
    store.count += 1
    stores.set(key, store)
  }

  return {
    allow: (key: string, nowMs: number) => {
      const store = getStore(key, nowMs)
      return store.count < MAX_REQUESTS
    },
    remaining: (key: string, nowMs: number) => {
      const store = getStore(key, nowMs)
      return Math.max(0, MAX_REQUESTS - store.count)
    },
    reset: (key: string) => {
      stores.delete(key)
    }
  }
}
