export function createRateLimiter(): RateLimiter {
  const map = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = map.get(key);
      if (!entry) {
        entry = { windowStart: nowMs, count: 0 };
        map.set(key, entry);
      }
      if (nowMs - entry.windowStart >= 1000) {
        entry.windowStart = nowMs;
        entry.count = 0;
      }
      if (entry.count < 3) {
        entry.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      let entry = map.get(key);
      if (!entry) {
        return 3;
      }
      if (nowMs - entry.windowStart >= 1000) {
        entry.windowStart = nowMs;
        entry.count = 0;
        return 3;
      }
      return 3 - entry.count;
    },
    reset(key: string): void {
      map.delete(key);
    }
  };
}
