export function createEventEmitter() {
  const events = new Map<string, Array<{ listener: Function, once: boolean }>>();

  return {
    on(event: string, listener: Function): number {
      const listeners = events.get(event) || [];
      listeners.push({ listener, once: false });
      events.set(event, listeners);
      return listeners.length;
    },
    once(event: string, listener: Function): number {
      const listeners = events.get(event) || [];
      listeners.push({ listener, once: true });
      events.set(event, listeners);
      return listeners.length;
    },
    off(event: string, listener: Function): boolean {
      const listeners = events.get(event) || [];
      const index = listeners.findIndex(l => l.listener === listener);
      if (index === -1) return false;
      listeners.splice(index, 1);
      events.set(event, listeners);
      return true;
    },
    emit(event: string, payload: any): any[] {
      const listeners = events.get(event) || [];
      const toProcess = [...listeners]; // copy to iterate over
      const results: any[] = [];
      for (const listener of toProcess) {
        results.push(listener.listener(payload));
        if (listener.once) {
          const index = listeners.indexOf(listener);
          if (index !== -1) {
            listeners.splice(index, 1);
          }
        }
      }
      events.set(event, listeners);
      return results;
    },
    listenerCount(event: string): number {
      const listeners = events.get(event) || [];
      return listeners.length;
    }
  };
}

