export function createEventEmitter(): EventEmitter {
  const listeners: { [event: string]: { regular: Listener[]; once: Listener[] } } = {};

  return {
    on(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = { regular: [], once: [] };
      }
      listeners[event].regular.push(listener);
      return listeners[event].regular.length;
    },

    once(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = { regular: [], once: [] };
      }
      listeners[event].once.push(listener);
      return listeners[event].once.length;
    },

    off(event: string, listener: Listener): boolean {
      if (!listeners[event]) return false;
      const idx = listeners[event].regular.indexOf(listener);
      if (idx !== -1) {
        listeners[event].regular.splice(idx, 1);
        return true;
      }
      const idxOnce = listeners[event].once.indexOf(listener);
      if (idxOnce !== -1) {
        listeners[event].once.splice(idxOnce, 1);
        return true;
      }
      return false;
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!listeners[event]) return [];
      const results: unknown[] = [];
      // Process regular listeners
      const regular = listeners[event].regular;
      for (const listener of regular) {
        results.push(listener(payload));
      }
      // Process once listeners
      const once = listeners[event].once;
      const onceCopy = [...once];
      for (const listener of onceCopy) {
        results.push(listener(payload));
        const idx = once.indexOf(listener);
        if (idx !== -1) {
          once.splice(idx, 1);
        }
      }
      return results;
    },

    listenerCount(event: string): number {
      if (!listeners[event]) return 0;
      return listeners[event].regular.length + listeners[event].once.length;
    }
  };
}
