class EventEmitter {
  private events = new Map<string, { regular: Function[]; once: Function[] }>();

  on(event: string, listener: Function): number {
    const entry = this.events.get(event) || { regular: [], once: [] };
    entry.regular.push(listener);
    this.events.set(event, entry);
    return entry.regular.length + entry.once.length;
  }

  once(event: string, listener: Function): number {
    const entry = this.events.get(event) || { regular: [], once: [] };
    entry.once.push(listener);
    this.events.set(event, entry);
    return entry.regular.length + entry.once.length;
  }

  off(event: string, listener: Function): boolean {
    const entry = this.events.get(event);
    if (!entry) return false;

    const regIndex = entry.regular.indexOf(listener);
    if (regIndex !== -1) {
      entry.regular.splice(regIndex, 1);
      return true;
    }

    const onceIndex = entry.once.indexOf(listener);
    if (onceIndex !== -1) {
      entry.once.splice(onceIndex, 1);
      return true;
    }

    return false;
  }

  emit(event: string, payload: any): Array<any> {
    const entry = this.events.get(event);
    if (!entry) return [];

    const { regular, once } = entry;

    const regularResults = regular.map(listener => listener(payload));
    const onceResults = once.map(listener => listener(payload));
    once.length = 0; // Clear the once array

    return [...regularResults, ...onceResults];
  }

  listenerCount(event: string): number {
    const entry = this.events.get(event);
    return entry ? entry.regular.length + entry.once.length : 0;
  }
}

export function createEventEmitter() {
  return new EventEmitter();
}
