```typescript
interface Listener {
  callback: (payload: unknown) => unknown;
  once: boolean;
}

interface EventEmitter {
  on(event: string, listener: (payload: unknown) => unknown): number;
  once(event: string, listener: (payload: unknown) => unknown): number;
  off(event: string, listener: (payload: unknown) => unknown): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

class EventEmitterImpl {
  private listeners: Map<string, Array<Listener>> = new Map();

  on(event: string, listener: (payload: unknown) => unknown): number {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    const entry: Listener = { callback: listener, once: false };
    this.listeners.get(event)!.push(entry);
    return this.listeners.get(event)!.length;
  }

  once(event: string, listener: (payload: unknown) => unknown): number {
    const entry: Listener = { callback: listener, once: true };
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event)!.push(entry);
    return this.listeners.get(event)!.length;
  }

  off(event: string, listener: (payload: unknown) => unknown): boolean {
    if (!this.listeners.has(event)) {
      return false;
    }
    const list = this.listeners.get(event)!;
    for (let i = 0; i < list.length; i++) {
      if (list[i].callback === listener) {
        list.splice(i, 1);
        return true;
      }
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    if (!this.listeners.has(event)) {
      return [];
    }
    const list = this.listeners.get(event)!;
    const results: unknown[] = [];
    for (let i = 0; i < list.length; i++) {
      const entry = list[i];
      if (entry.once) {
        this.off(event, entry.callback);
      }
      results.push(entry.callback(payload));
    }
    return results;
  }

  listenerCount(event: string): number {
    if (!this.listeners.has(event)) {
      return 0;
    }
    return this.listeners.get(event)!.length;
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitterImpl();
}
