export function createRateLimiter() {
  const stateMap = new Map<string, { windowStart: number, count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let state = stateMap.get(key);
      if (!state) {
        state = { windowStart: nowMs, count: 3 };
        stateMap.set(key, state);
      }

      const { windowStart, count } = state;

      if (nowMs >= windowStart + 1000) {
        state.windowStart = nowMs;
        state.count = 3;
      } else {
        if (count > 0) {
          state.count--;
          return true;
        }
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      let state = stateMap.get(key);
      if (!state) {
        state = { windowStart: nowMs, count: 3 };
        stateMap.set(key, state);
      }

      const { windowStart, count } = state;

      if (nowMs >= windowStart + 1000) {
        return 3;
      } else {
        return Math.max(0, count);
      }
    },

    reset(key: string): void {
      stateMap.delete(key);
    }
  };
}
