type Listener<T = unknown> = (payload: T) => unknown;

interface EventEmitter {
  on<T>(event: string, listener: Listener<T>): number;
  once<T>(event: string, listener: Listener<T>): number;
  off<T>(event: string, listener: Listener<T>): boolean;
  emit<T>(event: string, payload: T): unknown[];
  listenerCount(event: string): number;
}

function createEventEmitter(): EventEmitter {
  const listeners: Record<string, Listener[]> = {};
  const onceListeners: Record<string, Listener[]> = {};

  function on<T>(event: string, listener: Listener<T>): number {
    if (!listeners[event]) {
      listeners[event] = [];
    }
    listeners[event].push(listener);
    return listeners[event].length;
  }

  function once<T>(event: string, listener: Listener<T>): number {
    if (!onceListeners[event]) {
      onceListeners[event] = [];
    }
    onceListeners[event].push(listener);
    // Register a wrapper that removes itself after one call
    const wrapper: Listener<T> = (payload) => {
      off(event, wrapper);
      return listener(payload);
    };
    // Store mapping to allow removal via off()
    // We'll store the wrapper in both onceListeners and listeners for off() to find it
    onceListeners[event][onceListeners[event].length - 1] = wrapper;
    // Also register in main listeners to make off() work consistently
    if (!listeners[event]) {
      listeners[event] = [];
    }
    listeners[event].push(wrapper);
    return listeners[event].length;
  }

  function off<T>(event: string, listener: Listener<T>): boolean {
    if (!listeners[event]) {
      return false;
    }

    const index = listeners[event].indexOf(listener);
    if (index !== -1) {
      listeners[event].splice(index, 1);
      // Remove from onceListeners if present
      if (onceListeners[event]) {
        const onceIndex = onceListeners[event].indexOf(listener);
        if (onceIndex !== -1) {
          onceListeners[event].splice(onceIndex, 1);
        }
      }
      return true;
    }

    return false;
  }

  function emit<T>(event: string, payload: T): unknown[] {
    const results: unknown[] = [];

    // Collect listeners to avoid mutation issues during iteration
    const currentListeners = listeners[event] ? [...listeners[event]] : [];
    const currentOnceListeners = onceListeners[event] ? [...onceListeners[event]] : [];

    for (const listener of currentListeners) {
      const result = listener(payload);
      results.push(result);
    }

    // Clear once listeners after firing
    if (onceListeners[event]) {
      onceListeners[event] = [];
    }

    return results;
  }

  function listenerCount(event: string): number {
    return (listeners[event] ? listeners[event].length : 0);
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount
  };
}
