```typescript
interface RateLimiterState {
  count: number;
  windowStart: number;
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, RateLimiterState>();

  return {
    allow(key: string, nowMs: number): boolean {
      const keyState = state.get(key);

      if (!keyState || nowMs - keyState.windowStart >= windowMs) {
        state.set(key, { count: 1, windowStart: nowMs });
        return true;
      }

      if (keyState.count < limit) {
        keyState.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const keyState = state.get(key);

      if (!keyState || nowMs - keyState.windowStart >= windowMs) {
        return limit;
      }

      return Math.max(0, limit - keyState.count);
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}
