type WindowState = {
  count: number;
  windowStartMs: number;
};

export function createRateLimiter() {
  const windows = new Map<string, WindowState>();
  const MAX_REQUESTS = 3;
  const WINDOW_SIZE_MS = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      const state = windows.get(key);

      // No existing state or window has fully elapsed
      if (!state || nowMs - state.windowStartMs >= WINDOW_SIZE_MS) {
        windows.set(key, {
          count: 1,
          windowStartMs: nowMs
        });
        return true;
      }

      // Window is still active
      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = windows.get(key);

      if (!state || nowMs - state.windowStartMs >= WINDOW_SIZE_MS) {
        return MAX_REQUESTS;
      }

      return Math.max(0, MAX_REQUESTS - state.count);
    },

    reset(key: string): void {
      windows.delete(key);
    }
  };
}
