type WindowState = {
  count: number;
  windowStart: number;
};

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, WindowState>();

  function allow(key: string, nowMs: number): boolean {
    const keyState = state.get(key);

    if (!keyState || nowMs - keyState.windowStart >= windowMs) {
      state.set(key, {
        count: 1,
        windowStart: nowMs,
      });
      return true;
    }

    if (keyState.count < limit) {
      keyState.count++;
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const keyState = state.get(key);

    if (!keyState || nowMs - keyState.windowStart >= windowMs) {
      return limit;
    }

    return Math.max(0, limit - keyState.count);
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return {
    allow,
    remaining,
    reset,
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
