export function createRateLimiter() {
  const windows = new Map<string, { start: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const windowSize = 1000;
      const maxRequests = 3;

      const existing = windows.get(key);
      if (!existing || nowMs - existing.start >= windowSize) {
        windows.set(key, { start: nowMs, count: 1 });
        return true;
      }

      if (existing.count < maxRequests) {
        existing.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const windowSize = 1000;
      const maxRequests = 3;

      const existing = windows.get(key);
      if (!existing || nowMs - existing.start >= windowSize) {
        return maxRequests;
      }

      return Math.max(0, maxRequests - existing.count);
    },

    reset(key: string) {
      windows.delete(key);
    },
  };
}
