export function createRateLimiter() {
  const policy = { limit: 3, windowMs: 1000 };
  const internal = new Map<string, { history: number[] }>();

  return {
    allow(key: string, nowMs: number) {
      const { limit, windowMs } = policy;
      const state = internal.get(key) || { history: [nowMs] };
      let t0 = state.history.shift();
      const now = nowMs || Date.now();
      while (t0 && now - t0 > windowMs) {
        state.history.shift();
        t0 = state.history[0];
      }
      if (state.history.length < limit) {
        state.history.push(now);
        internal.set(key, state);
        return true;
      }
      internal.set(key, state);
      return false;
    },
    remaining(key: string, nowMs: number) {
      const state = internal.get(key) || { history: [nowMs] };
      let t0 = state.history.shift();
      const now = nowMs || Date.now();
      while (t0 && now - t0 > policy.windowMs) {
        state.history.shift();
        t0 = state.history[0];
      }
      const remaining = Math.max(0, policy.limit - state.history.length);
      internal.set(key, state);
      return remaining;
    },
    reset(key: string) {
      internal.delete(key);
    },
  };
}
