export function createEventEmitter() {
  const listeners = new Map<string, Set<(...args: unknown[]) => unknown>>();

  type Listener = (...args: unknown[]) => unknown;

  interface EventEmitter {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, ...args: unknown[]): unknown[];
    listenerCount(event: string): number;
  }

  return {
    on(event: string, listener: Listener) {
      if (!listeners.has(event)) {
        listeners.set(event, new Set());
      }
      const set = listeners.get(event)!;
      set.add(listener);
      return set.size;
    },
    once(event: string, listener: Listener) {
      function onceWrapper(...args: unknown[]) {
        listener(...args);
      }
      return this.on(event, onceWrapper);
    },
    off(event: string, listener: Listener) {
      if (!listeners.has(event)) return false;
      return listeners.get(event)!.delete(listener);
    },
    emit(event: string, ...args: unknown[]) {
      if (!listeners.has(event)) return [];
      return Array.from(listeners.get(event)!).map(fn => fn(...args));
    },
    listenerCount(event: string) {
      return listeners.get(event)?.size || 0;
    },
  };
