/**
 * Creates a TTL (Time-To-Live) cache implementation for in-memory key-value storage with expiration support.
 * This implementation supports TTL-based expiration for cache entries.
 * 
 * @returns An object with methods to set, get, has, delete, size and clear operations.
 */
export function createTtlCache() {
  // Internal map to store key-value pairs with expiration timestamps
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  /**
   * Sets a value in the cache with a specific expiration time.
   * If ttlMs is omitted, a default 1000ms expiration will be used.
   * 
   * @param key - The cache key to store the value under.
   * @param value - The value to store in the cache.
   * @param nowMs - The current timestamp in milliseconds (used for deterministic time handling).
   * @param ttlMs - The time-to-live in milliseconds before expiration. Defaults to 1000ms (1 second) if not provided.
   */
  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const expiresAt = ttlMs !== undefined 
      ? ttlMs <= 0 ? nowMs // Immediately expire if TTL is 0 or negative 
      : nowMs + ttlMs! // Expiration timestamp
    : nowMs + 1000; // Default 1000ms if TTL omitted

    // Overwrite or insert the entry with the expiration
    cache.set(key, { value, expiresAt });
  }

  /**
   * Gets a value from the cache.
   * If the key exists and is still valid (not expired), the stored value is returned.
   * Otherwise, undefined will be returned and the key will be removed from the cache.
   * 
   * @param key - The cache key to fetch.
   * @param nowMs - The current timestamp in milliseconds (used for deterministic time handling).
   * @returns The stored value if valid and not expired, otherwise undefined and the key is deleted from the cache.
   */
  function get(key: string, nowMs: number): unknown {
    const entry = cache.get(key);
    if (entry && entry.expiresAt > nowMs) {
      // Return the value if it's still valid
      return entry.value;
    }
    // Delete the expired entry and return nothing
    cache.delete(key);

    // Return undefined for any expired or missing keys
    return undefined;
  }

  /**
   * Checks if a key exists in the cache and whether it's validity.
   * 
   * @param key - The cache key to check.
   * @param nowMs - The current timestamp in milliseconds (used for deterministic time handling).
   * @returns True if the key exists and is valid (not expired), false if not found or expired.
   */
  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    return entry && entry.expiresAt > nowMs;
  }

  /**
   * Deletes a key from the cache.
   * 
   * @param key - The cache key to delete.
   * @returns True if the key existed before deletion, false if it didn't exist.
   */
  function delete(key: string): boolean {
    return cache.delete(key);
  }

  /**
   * Gets the number of currently valid non-expired entries in the cache.
   * 
   * @param nowMs - The current timestamp in milliseconds (used for deterministic time handling).
   * @returns The current count of live non-expired entries.
   */
  function size(nowMs: number): number {
    let count = 0;
    // Iterate only non-expired entries (fast, O(n) complexity, not O(n^2)
    for (const [key, entry] of cache) {
      if (entry.expiresAt > nowMs) {
        ++count;
      }
    }
    return count; // Live non-expired count
  }

  /**
   * Clears all entries from the cache, deleting all key-value pairs.
   */
  function clear(): void {
    cache.clear(); // Fast O(1) operation, not O(n)
  }

  // Export the createTtlCache function
  // This function is the public API for users to use
  return createTtlCache;
}
